insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f1000000-0000-0000-0000-000000000001', 'mrcp1', 'dfd19686-0722-4055-bf6a-4ed7a82f25c2',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f1000000-0000-0000-0000-000000000001', 'A', 'Await blood culture results before starting antibiotics', false, 'Ruled out because delaying antibiotics in sepsis significantly increases mortality; empirical broad-spectrum antibiotics should be given within the first hour, with cultures taken beforehand but not awaited.', 1),
('f1000000-0000-0000-0000-000000000001', 'B', 'Oral antibiotics and outpatient review', false, 'Ruled out because hypotension and raised lactate indicate significant sepsis requiring hospital admission and IV treatment, not outpatient oral therapy.', 2),
('f1000000-0000-0000-0000-000000000001', 'C', 'IV fluids alone without antibiotics', false, 'Ruled out because fluids alone do not address the underlying infective source; antibiotics are equally essential and must not be delayed.', 3),
('f1000000-0000-0000-0000-000000000001', 'D', 'Antipyretics only, with reassessment in 24 hours', false, 'Ruled out because this represents a life-threatening emergency requiring immediate, bundled intervention, not symptomatic treatment with delayed reassessment.', 4),
('f1000000-0000-0000-0000-000000000001', 'E', 'Begin the Sepsis Six bundle: blood cultures, IV antibiotics, IV fluids, lactate measurement, oxygen and urine output monitoring, all within the first hour', true, 'Correct. This patient meets criteria for sepsis (infection with organ dysfunction: hypotension, raised lactate, confusion); the Sepsis Six bundle, delivered within the first hour, is the evidence-based approach to reduce mortality, alongside identifying and controlling the likely urinary source.', 5),
('f1000000-0000-0000-0000-000000000002', 'A', 'Give further large-volume crystalloid boluses indefinitely without considering vasopressors', false, 'Ruled out because continuing fluid resuscitation alone, once adequate volume has been given without haemodynamic response, risks fluid overload without addressing the vasodilatory shock state; vasopressor support is needed.', 1),
('f1000000-0000-0000-0000-000000000002', 'B', 'Start broad-spectrum antibiotics for the first time at this point', false, 'Ruled out because antibiotics should already have been given within the first hour of recognising sepsis, not delayed until shock has developed; this step addresses a different (already overdue) part of management.', 2),
('f1000000-0000-0000-0000-000000000002', 'C', 'Give a single dose of oral antipyretic and reassess in 4 hours', false, 'Ruled out because septic shock requires urgent escalation of haemodynamic support, not symptomatic treatment with delayed reassessment.', 3),
('f1000000-0000-0000-0000-000000000002', 'D', 'Start a vasopressor (e.g. noradrenaline) and arrange transfer to a critical care setting', true, 'Correct. Persistent hypotension despite adequate fluid resuscitation defines septic shock; a vasopressor, typically noradrenaline, is required to restore adequate perfusion pressure, and the patient should be managed in a critical care environment with invasive monitoring.', 4),
('f1000000-0000-0000-0000-000000000002', 'E', 'Discharge home with safety-netting advice', false, 'Ruled out because persistent hypotension despite fluids indicates septic shock, a life-threatening condition requiring inpatient critical care management, not discharge.', 5),
('f1000000-0000-0000-0000-000000000003', 'A', 'Infective endocarditis', true, 'Correct. Fever, a new murmur, positive blood cultures for a typical organism (Staphylococcus aureus), and a vegetation on echocardiography in a patient who injects drugs (a major risk factor for right-sided endocarditis) together confirm infective endocarditis.', 1),
('f1000000-0000-0000-0000-000000000003', 'B', 'Rheumatic fever', false, 'Ruled out because rheumatic fever is a post-streptococcal inflammatory condition, not caused by Staphylococcus aureus bacteraemia, and would not show a vegetation with positive blood cultures for this organism.', 2),
('f1000000-0000-0000-0000-000000000003', 'C', 'Pericarditis', false, 'Ruled out because pericarditis causes chest pain and a pericardial rub, not a new murmur with a vegetation on echocardiography and positive blood cultures for Staphylococcus aureus.', 3),
('f1000000-0000-0000-0000-000000000003', 'D', 'Myocarditis', false, 'Ruled out because myocarditis does not typically cause a new murmur or a demonstrable valvular vegetation with bacteraemia; the clinical and echocardiographic picture here is specific to endocarditis.', 4),
('f1000000-0000-0000-0000-000000000003', 'E', 'Simple line infection without endocarditis', false, 'Ruled out because the presence of a demonstrated valvular vegetation on echocardiography confirms endocarditis, not simply an uncomplicated bloodstream infection.', 5),
('f1000000-0000-0000-0000-000000000004', 'A', 'Splinter haemorrhages', false, 'Ruled out because splinter haemorrhages are a minor Duke criterion (vascular phenomenon), not a major criterion.', 1),
('f1000000-0000-0000-0000-000000000004', 'B', 'Fever alone', false, 'Ruled out because fever alone is a minor Duke criterion, not sufficient by itself to be classified as a major criterion.', 2),
('f1000000-0000-0000-0000-000000000004', 'C', 'Positive blood cultures with a typical endocarditis organism from two separate cultures', true, 'Correct. Persistently positive blood cultures with a typical infective endocarditis organism (e.g. viridans streptococci, Staphylococcus aureus, HACEK organisms) from separate samples is one of the two major Duke criteria, the other being evidence of endocardial involvement on echocardiography.', 3),
('f1000000-0000-0000-0000-000000000004', 'D', 'A prosthetic heart valve (predisposing condition)', false, 'Ruled out because having a predisposing cardiac condition is a minor Duke criterion, reflecting increased risk rather than direct diagnostic evidence of active infection.', 4),
('f1000000-0000-0000-0000-000000000004', 'E', 'Malaise', false, 'Ruled out because non-specific systemic symptoms such as malaise are not part of the Duke criteria at all.', 5),
('f1000000-0000-0000-0000-000000000005', 'A', 'Further large-volume crystalloid boluses only', false, 'Ruled out because the shock is already refractory to fluids and vasopressors; additional fluid alone is unlikely to help and risks fluid overload.', 1),
('f1000000-0000-0000-0000-000000000005', 'B', 'IV hydrocortisone', true, 'Correct. In septic shock refractory to fluids and escalating vasopressor therapy, particularly with evidence suggesting relative adrenal insufficiency, IV hydrocortisone can help improve haemodynamic stability by restoring an adequate cortisol response to severe physiological stress.', 2),
('f1000000-0000-0000-0000-000000000005', 'C', 'Stop the noradrenaline infusion', false, 'Ruled out because stopping vasopressor support in ongoing septic shock would cause further haemodynamic deterioration; the vasopressor should be continued (and hydrocortisone added), not withdrawn.', 3),
('f1000000-0000-0000-0000-000000000005', 'D', 'Start high-dose insulin therapy', false, 'Ruled out because there is no indication of a glycaemic emergency here; insulin has no specific role in managing refractory septic shock in this context.', 4),
('f1000000-0000-0000-0000-000000000005', 'E', 'Broad-spectrum antibiotics for the first time at this stage', false, 'Ruled out because antibiotics should already have been started promptly on recognition of sepsis, not introduced for the first time only once shock has become refractory.', 5),
('f1000000-0000-0000-0000-000000000006', 'A', 'Overwhelming post-splenectomy infection (OPSI) with an encapsulated organism', true, 'Correct. Asplenic patients are at high risk of overwhelming, rapidly progressive sepsis from encapsulated organisms (Streptococcus pneumoniae, Haemophilus influenzae, Neisseria meningitidis), as the spleen normally plays a key role in clearing these organisms from the bloodstream; this is a recognised medical emergency.', 1),
('f1000000-0000-0000-0000-000000000006', 'B', 'Simple viral upper respiratory tract infection', false, 'Ruled out because a viral URTI would not typically cause this rapid, life-threatening deterioration with fever and confusion in a patient with a specific known risk factor (asplenia) for overwhelming bacterial sepsis.', 2),
('f1000000-0000-0000-0000-000000000006', 'C', 'Malaria', false, 'Ruled out because there is no travel history given, and while malaria can cause severe illness, the specific risk factor (splenectomy) and rapid course described are most classically linked to OPSI from encapsulated bacteria.', 3),
('f1000000-0000-0000-0000-000000000006', 'D', 'Anaphylaxis', false, 'Ruled out because there is no exposure to a known allergen described, and the presentation (fever, rigors, confusion) is infective rather than allergic in nature.', 4),
('f1000000-0000-0000-0000-000000000006', 'E', 'Simple urinary tract infection', false, 'Ruled out because a straightforward UTI would not typically cause this degree of rapid systemic deterioration, and the key risk factor here (asplenia) points specifically to overwhelming infection with encapsulated organisms.', 5),
('f1000000-0000-0000-0000-000000000007', 'A', 'Oral amoxicillin', false, 'Ruled out because oral antibiotics are inadequate for this life-threatening emergency, which requires immediate parenteral, broad-spectrum antibiotic therapy.', 1),
('f1000000-0000-0000-0000-000000000007', 'B', 'IV ceftriaxone', true, 'Correct. Suspected meningococcal septicaemia with a purpuric rash and shock is a medical emergency; empirical IV ceftriaxone (a third-generation cephalosporin with good CNS penetration and Neisseria meningitidis coverage) should be given immediately, without waiting for culture confirmation.', 2),
('f1000000-0000-0000-0000-000000000007', 'C', 'IV vancomycin alone', false, 'Ruled out because vancomycin alone does not provide reliable Gram-negative (including meningococcal) coverage; a cephalosporin such as ceftriaxone is the appropriate empirical choice.', 3),
('f1000000-0000-0000-0000-000000000007', 'D', 'Topical antiseptic to the rash only', false, 'Ruled out because a purpuric rash in meningococcal septicaemia reflects systemic bacteraemia and endothelial damage, not a local skin process; systemic antibiotics are required, not topical treatment.', 4),
('f1000000-0000-0000-0000-000000000007', 'E', 'Await lumbar puncture results before starting any antibiotics', false, 'Ruled out because delaying antibiotics for confirmatory testing in suspected meningococcal septicaemia significantly increases mortality; empirical treatment must start immediately on clinical suspicion.', 5),
('f1000000-0000-0000-0000-000000000008', 'A', 'Secondary bacterial peritonitis (e.g. from bowel perforation)', false, 'Ruled out because secondary peritonitis typically shows a much higher neutrophil count with multiple organisms on culture and evidence of a surgical source (e.g. free air, localised collection) on imaging, which is not described here; the neutrophil count and typical clinical context favour spontaneous, not secondary, peritonitis.', 1),
('f1000000-0000-0000-0000-000000000008', 'B', 'Tuberculous peritonitis', false, 'Ruled out because TB peritonitis typically causes a lymphocyte-predominant ascitic fluid picture, not the neutrophil-predominant pattern described here.', 2),
('f1000000-0000-0000-0000-000000000008', 'C', 'Malignant ascites', false, 'Ruled out because malignant ascites typically shows a lower neutrophil count without the acute infective picture (fever, abdominal pain) described, and would usually show malignant cells on cytology rather than a neutrophilic exudate.', 3),
('f1000000-0000-0000-0000-000000000008', 'D', 'Simple decompensated cirrhosis without infection', false, 'Ruled out because an ascitic neutrophil count above 250 cells/microlitre specifically indicates infection (SBP), not simply uncomplicated ascites from liver disease.', 4),
('f1000000-0000-0000-0000-000000000008', 'E', 'Spontaneous bacterial peritonitis', true, 'Correct. An ascitic fluid neutrophil count above 250 cells/microlitre in a patient with cirrhosis and ascites, with fever and abdominal pain, is diagnostic of spontaneous bacterial peritonitis, an infection of ascitic fluid without an evident intra-abdominal surgical source.', 5),
('f1000000-0000-0000-0000-000000000009', 'A', 'Contamination of the peripheral blood culture', false, 'Ruled out because the pattern described (catheter sample positive earlier, both growing the same organism) is the classic evidence supporting a true catheter-related infection, not simple peripheral contamination.', 1),
('f1000000-0000-0000-0000-000000000009', 'B', 'Infective endocarditis unrelated to the catheter', false, 'Ruled out because there is no murmur or other endocarditis feature described, and the specific culture timing pattern points to the catheter itself as the source.', 2),
('f1000000-0000-0000-0000-000000000009', 'C', 'Catheter-related bloodstream infection', true, 'Correct. Fever with no other source, and blood cultures from the catheter becoming positive significantly earlier than paired peripheral cultures (differential time to positivity), is a validated method for diagnosing catheter-related bloodstream infection without needing to remove the line for culture.', 3),
('f1000000-0000-0000-0000-000000000009', 'D', 'Urinary tract infection', false, 'Ruled out because there is no urinary source described, and the differential time to positivity finding specifically implicates the central line as the source of bacteraemia.', 4),
('f1000000-0000-0000-0000-000000000009', 'E', 'Community-acquired pneumonia', false, 'Ruled out because there is no respiratory source described, and the culture pattern points specifically to the catheter as the source of infection.', 5),
('f1000000-0000-0000-0000-000000000010', 'A', 'Contamination of both blood culture sets', false, 'Ruled out because contamination is far more typically associated with skin commensals (e.g. coagulase-negative staphylococci) growing in only one of several sets, not a recognised pathogen like E. coli growing concordantly from two separately drawn samples.', 1),
('f1000000-0000-0000-0000-000000000010', 'B', 'Normal finding requiring no action', false, 'Ruled out because bacteraemia with a recognised pathogen in a febrile patient is a significant finding requiring identification of the source and antibiotic treatment, not disregard.', 2),
('f1000000-0000-0000-0000-000000000010', 'C', 'Laboratory error', false, 'Ruled out because concordant growth of the same organism from two independently drawn samples makes laboratory error very unlikely; this pattern is the standard evidence used to confirm true bacteraemia.', 3),
('f1000000-0000-0000-0000-000000000010', 'D', 'True bacteraemia', true, 'Correct. Growth of the same organism (E. coli, a recognised pathogen rather than a typical skin contaminant) from two separate blood culture sets, in a febrile patient, indicates true bacteraemia rather than contamination, and warrants a search for the underlying source (e.g. urinary tract) and appropriate antibiotic treatment.', 4),
('f1000000-0000-0000-0000-000000000010', 'E', 'Chronic asymptomatic carriage requiring no treatment', false, 'Ruled out because bacteraemia (organisms in the bloodstream) with fever is an active infective process requiring treatment, not a benign carriage state.', 5),
('f1000000-0000-0000-0000-000000000011', 'A', 'Community-acquired bacterial pneumonia', false, 'Ruled out because typical bacterial pneumonia usually presents more acutely with focal consolidation and productive cough, rather than the subacute, bilateral, interstitial pattern with marked exertional desaturation described here.', 1),
('f1000000-0000-0000-0000-000000000011', 'B', 'Pneumocystis jirovecii pneumonia', true, 'Correct. A subacute onset of dry cough and breathlessness with bilateral interstitial infiltrates and marked exertional desaturation, in a patient with advanced HIV (CD4 <200), is classic for Pneumocystis jirovecii pneumonia (PCP), an AIDS-defining opportunistic infection.', 2),
('f1000000-0000-0000-0000-000000000011', 'C', 'Pulmonary tuberculosis', false, 'Ruled out because although TB is an important differential in HIV, the classic subacute presentation with marked exertional desaturation and bilateral perihilar interstitial infiltrates (without cavitation or apical predominance described) is more typical of PCP.', 3),
('f1000000-0000-0000-0000-000000000011', 'D', 'Pulmonary Kaposi sarcoma', false, 'Ruled out because pulmonary Kaposi sarcoma typically causes nodular infiltrates, often with skin lesions present, not this classic bilateral interstitial pattern with profound desaturation on exertion.', 4),
('f1000000-0000-0000-0000-000000000011', 'E', 'Asthma exacerbation', false, 'Ruled out because there is no history of wheeze or prior asthma, and the clinical context (advanced HIV, subacute course, bilateral interstitial infiltrates) points specifically to an opportunistic infection.', 5),
('f1000000-0000-0000-0000-000000000012', 'A', 'Toxoplasma encephalitis', false, 'Ruled out because toxoplasmosis typically causes focal neurological signs with ring-enhancing lesions on CT/MRI, not the meningitic picture with a positive India ink stain described here.', 1),
('f1000000-0000-0000-0000-000000000012', 'B', 'HIV-associated dementia', false, 'Ruled out because HIV-associated dementia is a more gradual, progressive cognitive decline without the acute meningitic features (headache, fever, raised opening pressure, positive CSF stain) described here.', 2),
('f1000000-0000-0000-0000-000000000012', 'C', 'Bacterial meningitis', false, 'Ruled out because the subacute course and specifically positive India ink stain point to a fungal (cryptococcal), not bacterial, cause.', 3),
('f1000000-0000-0000-0000-000000000012', 'D', 'Cryptococcal meningitis', true, 'Correct. Subacute headache and fever with a raised CSF opening pressure and a positive India ink stain (demonstrating encapsulated yeast) in a patient with a very low CD4 count is characteristic of cryptococcal meningitis, an important opportunistic CNS infection in advanced HIV.', 4),
('f1000000-0000-0000-0000-000000000012', 'E', 'Progressive multifocal leukoencephalopathy', false, 'Ruled out because PML typically causes focal neurological deficits from demyelinating white matter lesions on MRI, not a meningitic picture with a positive India ink stain.', 5),
('f1000000-0000-0000-0000-000000000013', 'A', 'Primary CNS lymphoma', false, 'Ruled out because although CNS lymphoma is an important differential for ring-enhancing lesions in HIV, it is typically a single (rather than multiple) lesion; multiple lesions favour toxoplasmosis as the more likely diagnosis, often confirmed by response to empirical anti-toxoplasma treatment.', 1),
('f1000000-0000-0000-0000-000000000013', 'B', 'Cryptococcal meningitis', false, 'Ruled out because cryptococcal meningitis typically causes a meningitic picture (headache, raised CSF pressure) rather than discrete ring-enhancing mass lesions with focal neurological deficits.', 2),
('f1000000-0000-0000-0000-000000000013', 'C', 'Toxoplasma encephalitis', true, 'Correct. Multiple ring-enhancing brain lesions with focal neurological deficits in a patient with advanced HIV (CD4 <100) is classic for cerebral toxoplasmosis, the most common cause of a focal brain lesion in this population, typically from reactivation of latent infection.', 3),
('f1000000-0000-0000-0000-000000000013', 'D', 'Progressive multifocal leukoencephalopathy', false, 'Ruled out because PML typically causes non-enhancing white matter lesions without the mass effect or ring enhancement described here.', 4),
('f1000000-0000-0000-0000-000000000013', 'E', 'Bacterial brain abscess', false, 'Ruled out because although bacterial abscess can cause a ring-enhancing lesion, the specific context of advanced HIV with multiple lesions makes toxoplasmosis the most likely diagnosis, particularly as first-line management is often empirical anti-toxoplasma treatment with response assessed on repeat imaging.', 5),
('f1000000-0000-0000-0000-000000000014', 'A', 'Oesophageal candidiasis', true, 'Correct. Odynophagia/dysphagia with white plaques on oesophageal endoscopy, in a patient with a CD4 count below 200, is characteristic of oesophageal candidiasis, an AIDS-defining opportunistic infection.', 1),
('f1000000-0000-0000-0000-000000000014', 'B', 'Gastro-oesophageal reflux disease', false, 'Ruled out because GORD does not typically cause white plaques on endoscopy; the endoscopic appearance described is specific to Candida infection.', 2),
('f1000000-0000-0000-0000-000000000014', 'C', 'Oesophageal carcinoma', false, 'Ruled out because carcinoma would typically present as a mass or stricture rather than diffuse white plaques, and the clinical context (advanced HIV) points more specifically to an opportunistic infection.', 3),
('f1000000-0000-0000-0000-000000000014', 'D', 'Herpes simplex oesophagitis', false, 'Ruled out because HSV oesophagitis typically causes discrete punched-out ulcers rather than the white plaques described, which are characteristic of Candida.', 4),
('f1000000-0000-0000-0000-000000000014', 'E', 'Achalasia', false, 'Ruled out because achalasia causes dysphagia to both solids and liquids from birds-beak narrowing on imaging, without the white plaques seen on endoscopy in this case.', 5),
('f1000000-0000-0000-0000-000000000015', 'A', 'Treatment failure of the antiretroviral regimen', false, 'Ruled out because treatment failure would be reflected by a failure of CD4 count to rise or viral load to fall, the opposite of what is described here, where these markers are improving despite clinical worsening.', 1),
('f1000000-0000-0000-0000-000000000015', 'B', 'A new, unrelated opportunistic infection', false, 'Ruled out because although this is always a differential to consider, the classic temporal pattern (worsening shortly after starting ART, with improving immunological markers) is most consistent with IRIS rather than coincidental new infection.', 2),
('f1000000-0000-0000-0000-000000000015', 'C', 'Drug-induced pneumonitis from the antiretroviral regimen', false, 'Ruled out because although drug toxicity is a differential, the specific pattern of worsening symptoms alongside improving CD4/viral load in the early weeks after starting ART is the hallmark of IRIS.', 3),
('f1000000-0000-0000-0000-000000000015', 'D', 'Progression of underlying HIV disease', false, 'Ruled out because disease progression would be reflected by worsening (not improving) immunological markers, the opposite of what is described.', 4),
('f1000000-0000-0000-0000-000000000015', 'E', 'Immune reconstitution inflammatory syndrome (IRIS)', true, 'Correct. Paradoxical clinical worsening shortly after starting antiretroviral therapy, despite improving immunological markers (rising CD4, falling viral load), reflects an exaggerated inflammatory response to a pre-existing (often subclinical) infection as the immune system recovers -- immune reconstitution inflammatory syndrome.', 5),
('f1000000-0000-0000-0000-000000000016', 'A', 'Formula feeding alone without antiretroviral therapy', false, 'Ruled out because avoiding breastfeeding reduces one route of transmission but is far less important than achieving maternal viral suppression, which addresses transmission risk throughout pregnancy and delivery, not just postnatally.', 1),
('f1000000-0000-0000-0000-000000000016', 'B', 'Maintaining maternal viral suppression on antiretroviral therapy', true, 'Correct. Achieving and maintaining an undetectable maternal viral load through effective antiretroviral therapy is the single most effective intervention for reducing mother-to-child transmission of HIV, dramatically lowering transmission risk regardless of delivery mode when viral load is well controlled.', 2),
('f1000000-0000-0000-0000-000000000016', 'C', 'Elective caesarean section regardless of viral load', false, 'Ruled out because with a well-suppressed viral load, vaginal delivery carries a very low transmission risk, and caesarean section is specifically reserved for cases with a detectable or high viral load near delivery, not routinely recommended when viral suppression is achieved.', 3),
('f1000000-0000-0000-0000-000000000016', 'D', 'Withholding antiretroviral therapy until after delivery', false, 'Ruled out because withholding treatment during pregnancy would leave the mother viraemic, significantly increasing transmission risk; continuing antiretroviral therapy throughout pregnancy is essential.', 4),
('f1000000-0000-0000-0000-000000000016', 'E', 'Vaccinating the mother against HIV during pregnancy', false, 'Ruled out because there is no licensed HIV vaccine; the most effective proven strategy is maternal viral suppression through antiretroviral therapy.', 5),
('f1000000-0000-0000-0000-000000000017', 'A', 'Wait for HIV testing results before considering any treatment', false, 'Ruled out because PEP effectiveness depends on prompt initiation after exposure; waiting for testing (which may take time and cannot exclude a very recent seroconversion window) would unacceptably delay treatment.', 1),
('f1000000-0000-0000-0000-000000000017', 'B', 'No action needed unless symptoms develop', false, 'Ruled out because HIV infection is often asymptomatic in the early stages, and waiting for symptoms would miss the window in which PEP is effective.', 2),
('f1000000-0000-0000-0000-000000000017', 'C', 'Start post-exposure prophylaxis (PEP) as soon as possible, ideally within 72 hours of exposure', true, 'Correct. Following a high-risk sexual exposure of uncertain HIV status, post-exposure prophylaxis with a combination antiretroviral regimen should be started as soon as possible (ideally within hours, and no later than 72 hours) to reduce the risk of HIV acquisition, continued for 28 days.', 3),
('f1000000-0000-0000-0000-000000000017', 'D', 'Start pre-exposure prophylaxis (PrEP) instead of PEP', false, 'Ruled out because PrEP is used to prevent HIV acquisition before an exposure occurs, not as treatment after a specific high-risk exposure has already happened, for which PEP is the appropriate intervention.', 4),
('f1000000-0000-0000-0000-000000000017', 'E', 'Administer the HIV vaccine', false, 'Ruled out because no licensed HIV vaccine exists; PEP with antiretroviral drugs is the evidence-based post-exposure intervention.', 5),
('f1000000-0000-0000-0000-000000000018', 'A', 'Disseminated Mycobacterium avium complex infection', true, 'Correct. Systemic symptoms (weight loss, night sweats, diarrhoea) with positive blood cultures for Mycobacterium avium complex, in a patient with a very low CD4 count (typically below 50), is characteristic of disseminated MAC infection, an AIDS-defining opportunistic infection.', 1),
('f1000000-0000-0000-0000-000000000018', 'B', 'Pulmonary tuberculosis', false, 'Ruled out because although TB is an important consideration in HIV, the blood culture growth of Mycobacterium avium complex (rather than Mycobacterium tuberculosis) specifically identifies MAC as the causative organism here.', 2),
('f1000000-0000-0000-0000-000000000018', 'C', 'Cytomegalovirus colitis', false, 'Ruled out because although CMV can cause diarrhoea in advanced HIV, the positive blood cultures for Mycobacterium avium complex specifically identify MAC, not CMV, as the cause in this case.', 3),
('f1000000-0000-0000-0000-000000000018', 'D', 'Cryptosporidiosis', false, 'Ruled out because cryptosporidiosis causes diarrhoea but is diagnosed by stool microscopy for oocysts, not blood culture growth of Mycobacterium avium complex.', 4),
('f1000000-0000-0000-0000-000000000018', 'E', 'Simple gastroenteritis', false, 'Ruled out because the systemic symptoms, chronicity, and positive blood cultures for a specific opportunistic organism indicate disseminated infection, not a self-limiting gastroenteritis.', 5),
('f1000000-0000-0000-0000-000000000019', 'A', 'Reduced risk of all comorbidities compared with the general population', false, 'Ruled out because well-controlled HIV does not confer protection against other conditions; in fact, several comorbidities (cardiovascular disease, certain cancers, osteoporosis) occur at higher rates even with good viral suppression.', 1),
('f1000000-0000-0000-0000-000000000019', 'B', 'No increased risk of any condition once viral load is undetectable', false, 'Ruled out because although viral suppression greatly reduces AIDS-defining illness risk, it does not eliminate the excess risk of certain non-AIDS-defining conditions, particularly cardiovascular disease, seen in people living with HIV.', 2),
('f1000000-0000-0000-0000-000000000019', 'C', 'Guaranteed normal life expectancy identical to an HIV-negative person of the same age with no additional monitoring needed', false, 'Ruled out because although life expectancy has improved dramatically with effective treatment, ongoing monitoring for comorbidities (including cardiovascular risk) remains an important part of routine HIV care.', 3),
('f1000000-0000-0000-0000-000000000019', 'D', 'Complete elimination of opportunistic infection risk with no further monitoring required', false, 'Ruled out because although risk is greatly reduced with a preserved CD4 count, routine monitoring (CD4 count, viral load) continues to be part of standard care, and this question specifically concerns increased, not eliminated, risk.', 4),
('f1000000-0000-0000-0000-000000000019', 'E', 'Cardiovascular disease', true, 'Correct. Despite effective antiretroviral therapy and good immunological/virological control, people living with HIV have an increased risk of cardiovascular disease compared with the general population, related to chronic low-grade inflammation, some antiretroviral drug effects, and a higher prevalence of traditional risk factors, warranting proactive cardiovascular risk assessment and management.', 5),
('f1000000-0000-0000-0000-000000000020', 'A', 'Full blood count and CRP alone', false, 'Ruled out because although a full blood count and CRP provide general information, they do not specifically measure the degree of HIV-related immunosuppression or virological control in the way CD4 count and viral load do.', 1),
('f1000000-0000-0000-0000-000000000020', 'B', 'Liver function tests alone', false, 'Ruled out because liver function tests are used to monitor for drug toxicity (relevant to some antiretrovirals) but do not directly reflect HIV disease status or treatment response.', 2),
('f1000000-0000-0000-0000-000000000020', 'C', 'ESR alone', false, 'Ruled out because ESR is a non-specific inflammatory marker and is not used as a specific measure of HIV disease progression or treatment response.', 3),
('f1000000-0000-0000-0000-000000000020', 'D', 'CD4 count and HIV viral load', true, 'Correct. CD4 count (reflecting the degree of immunosuppression) and HIV viral load (reflecting how well antiretroviral therapy is suppressing viral replication) are the two key tests used to monitor HIV disease status, guide treatment decisions, and assess response to therapy.', 4),
('f1000000-0000-0000-0000-000000000020', 'E', 'Random blood glucose alone', false, 'Ruled out because blood glucose has no role in monitoring HIV disease status; it may be relevant for metabolic side effects of some antiretrovirals but is not a core HIV monitoring test.', 5),
('f1000000-0000-0000-0000-000000000021', 'A', 'Plasmodium vivax', false, 'Ruled out because although P. vivax also causes malaria, it is far less common in West Africa (where Duffy-negativity confers relative resistance) than in South Asia or South America; P. falciparum is the most likely species from this travel history.', 1),
('f1000000-0000-0000-0000-000000000021', 'B', 'Plasmodium falciparum', true, 'Correct. Fever in a returning traveller from a malaria-endemic region (particularly sub-Saharan Africa) with ring forms on blood film is most likely to be Plasmodium falciparum, the species responsible for the large majority of malaria cases and nearly all severe/life-threatening disease acquired in this region.', 2),
('f1000000-0000-0000-0000-000000000021', 'C', 'Plasmodium ovale', false, 'Ruled out because P. ovale is a less common cause of malaria overall, and P. falciparum remains statistically the most likely causative species given the travel history to West Africa.', 3),
('f1000000-0000-0000-0000-000000000021', 'D', 'Borrelia recurrentis', false, 'Ruled out because although relapsing fever from Borrelia can cause cyclical fevers, the blood film finding of intraerythrocytic ring forms is specific to malaria parasites, not spirochaetes.', 4),
('f1000000-0000-0000-0000-000000000021', 'E', 'Dengue virus', false, 'Ruled out because dengue does not produce ring forms on a blood film; this finding is specific to malaria parasitaemia.', 5),
('f1000000-0000-0000-0000-000000000022', 'A', 'Oral artemether-lumefantrine', false, 'Ruled out because oral therapy is inadequate for severe malaria with organ dysfunction and altered consciousness; parenteral treatment is required.', 1),
('f1000000-0000-0000-0000-000000000022', 'B', 'Oral chloroquine', false, 'Ruled out because chloroquine resistance is widespread in P. falciparum in this region, and oral therapy is inappropriate for severe malaria regardless of drug choice.', 2),
('f1000000-0000-0000-0000-000000000022', 'C', 'Watchful waiting with antipyretics only', false, 'Ruled out because severe malaria with multi-organ involvement is a medical emergency with significant mortality if untreated; supportive care alone is inadequate.', 3),
('f1000000-0000-0000-0000-000000000022', 'D', 'IV artesunate', true, 'Correct. Severe falciparum malaria, indicated here by parasitaemia above 2%, confusion (cerebral malaria), hypoglycaemia and acute kidney injury, requires urgent treatment with IV artesunate, which has been shown to reduce mortality compared with IV quinine.', 4),
('f1000000-0000-0000-0000-000000000022', 'E', 'Oral doxycycline monotherapy', false, 'Ruled out because doxycycline is used as an adjunct or for prophylaxis, not as monotherapy for severe, life-threatening falciparum malaria requiring urgent parenteral antimalarial treatment.', 5),
('f1000000-0000-0000-0000-000000000023', 'A', 'Malaria', false, 'Ruled out because malaria does not typically cause the combination of retro-orbital headache, maculopapular rash and marked thrombocytopenia with bleeding seen here; these features are more specific to dengue.', 1),
('f1000000-0000-0000-0000-000000000023', 'B', 'Typhoid fever', false, 'Ruled out because typhoid typically causes a stepwise fever with relative bradycardia and rose spots, not the retro-orbital headache and marked thrombocytopenia with bleeding described here.', 2),
('f1000000-0000-0000-0000-000000000023', 'C', 'Dengue fever', true, 'Correct. High fever with severe retro-orbital headache, myalgia, a maculopapular rash, and thrombocytopenia with bleeding tendency, in a traveller returning from a dengue-endemic region (Southeast Asia), is characteristic of dengue fever, transmitted by Aedes mosquitoes.', 3),
('f1000000-0000-0000-0000-000000000023', 'D', 'Chikungunya', false, 'Ruled out because although chikungunya shares some features with dengue (fever, rash, myalgia), it is more classically associated with severe, often prolonged joint pain rather than the significant thrombocytopenia and bleeding tendency seen here.', 4),
('f1000000-0000-0000-0000-000000000023', 'E', 'Leptospirosis', false, 'Ruled out because leptospirosis typically presents with conjunctival suffusion and possible jaundice/renal impairment in severe cases, not this specific pattern of retro-orbital headache with marked thrombocytopenia and bleeding.', 5),
('f1000000-0000-0000-0000-000000000024', 'A', 'Malaria', false, 'Ruled out because malaria typically causes cyclical fever with rigors rather than this gradual stepwise pattern, and does not cause rose spots or relative bradycardia.', 1),
('f1000000-0000-0000-0000-000000000024', 'B', 'Dengue fever', false, 'Ruled out because dengue causes a more acute-onset high fever with retro-orbital headache and often thrombocytopenia with bleeding, not the gradual stepwise fever, rose spots and relative bradycardia described here.', 2),
('f1000000-0000-0000-0000-000000000024', 'C', 'Viral gastroenteritis', false, 'Ruled out because simple viral gastroenteritis does not cause this specific combination of stepwise fever, relative bradycardia and rose spots, which are classic for typhoid.', 3),
('f1000000-0000-0000-0000-000000000024', 'D', 'Hepatitis A', false, 'Ruled out because hepatitis A typically presents with jaundice and marked liver function derangement, not the specific fever pattern, rose spots and relative bradycardia described here.', 4),
('f1000000-0000-0000-0000-000000000024', 'E', 'Typhoid fever', true, 'Correct. A gradually stepwise-rising fever over days, relative bradycardia (Faget sign), abdominal symptoms with constipation, and rose spots on the trunk, in a traveller returning from an endemic region, is characteristic of typhoid fever caused by Salmonella typhi.', 5),
('f1000000-0000-0000-0000-000000000025', 'A', 'Onchocerciasis', true, 'Correct. Itchy skin nodules (containing adult worms) and progressive visual impairment, with microfilariae demonstrated on skin snips, in a patient from an endemic area of sub-Saharan Africa, is characteristic of onchocerciasis (river blindness), caused by Onchocerca volvulus and transmitted by blackfly bites.', 1),
('f1000000-0000-0000-0000-000000000025', 'B', 'Lymphatic filariasis', false, 'Ruled out because lymphatic filariasis classically causes limb or genital lymphoedema (elephantiasis) from lymphatic obstruction, not the itchy skin nodules and ocular involvement with microfilariae on skin snip seen in onchocerciasis.', 2),
('f1000000-0000-0000-0000-000000000025', 'C', 'Schistosomiasis', false, 'Ruled out because schistosomiasis typically causes haematuria (urinary schistosomiasis) or GI/hepatic symptoms (intestinal schistosomiasis), not itchy skin nodules with microfilariae on skin snip.', 3),
('f1000000-0000-0000-0000-000000000025', 'D', 'Loiasis', false, 'Ruled out because loiasis classically causes transient subcutaneous (Calabar) swellings and eye worm migration visible across the conjunctiva, not skin nodules with microfilariae specifically demonstrated on skin snip, which is the diagnostic method for onchocerciasis.', 4),
('f1000000-0000-0000-0000-000000000025', 'E', 'Scabies', false, 'Ruled out because although scabies causes itching, it does not cause visual disturbance or show microfilariae on skin snip, which specifically confirms a filarial infection.', 5),
('f1000000-0000-0000-0000-000000000026', 'A', 'Urinary tract infection', false, 'Ruled out because a standard bacterial UTI would not show terminal-spined ova on urine microscopy; this finding is specific to Schistosoma haematobium infection.', 1),
('f1000000-0000-0000-0000-000000000026', 'B', 'Urinary schistosomiasis (Schistosoma haematobium)', true, 'Correct. Fever and malaise following freshwater exposure in an endemic region, with haematuria and terminal-spined ova on urine microscopy, is characteristic of urinary schistosomiasis caused by Schistosoma haematobium, acquired through skin penetration by cercariae released from infected freshwater snails.', 2),
('f1000000-0000-0000-0000-000000000026', 'C', 'Renal tuberculosis', false, 'Ruled out because although TB can cause haematuria, the specific finding of terminal-spined ova on urine microscopy is diagnostic of schistosomiasis, not TB.', 3),
('f1000000-0000-0000-0000-000000000026', 'D', 'Bladder carcinoma', false, 'Ruled out because although chronic S. haematobium infection is itself a risk factor for bladder cancer, the acute presentation here with terminal-spined ova on microscopy points to active schistosomiasis rather than malignancy.', 4),
('f1000000-0000-0000-0000-000000000026', 'E', 'Renal calculi', false, 'Ruled out because renal stones cause haematuria typically with colicky pain, not the specific finding of terminal-spined ova, which confirms schistosomiasis.', 5),
('f1000000-0000-0000-0000-000000000027', 'A', $x$Leptospirosis (Weil's disease)$x$, true, $x$Correct. Fever, jaundice, acute kidney injury, severe myalgia (especially calf tenderness), and conjunctival suffusion following exposure to floodwater (contaminated by animal urine) is characteristic of severe leptospirosis (Weil's disease), caused by Leptospira species.$x$, 1),
('f1000000-0000-0000-0000-000000000027', 'B', 'Viral hepatitis', false, 'Ruled out because viral hepatitis alone does not typically cause conjunctival suffusion, acute kidney injury, or the severe myalgia described, which together point specifically to leptospirosis.', 2),
('f1000000-0000-0000-0000-000000000027', 'C', 'Malaria', false, 'Ruled out because malaria does not cause conjunctival suffusion, and the combination of jaundice, renal impairment and severe myalgia following floodwater exposure is more specific to leptospirosis.', 3),
('f1000000-0000-0000-0000-000000000027', 'D', 'Dengue fever', false, 'Ruled out because although dengue can cause fever and myalgia, it does not typically cause conjunctival suffusion or the marked renal impairment with jaundice seen in severe leptospirosis.', 4),
('f1000000-0000-0000-0000-000000000027', 'E', 'Typhoid fever', false, 'Ruled out because typhoid does not cause conjunctival suffusion, and the specific exposure history (floodwater) and clinical picture (jaundice, AKI, severe myalgia) point to leptospirosis.', 5),
('f1000000-0000-0000-0000-000000000028', 'A', 'Chemoprophylaxis alone, with no need for bite avoidance measures', false, 'Ruled out because no chemoprophylaxis regimen is 100% effective, so bite avoidance measures remain essential even when taking prophylaxis.', 1),
('f1000000-0000-0000-0000-000000000028', 'B', 'Bite avoidance measures alone, without chemoprophylaxis', false, 'Ruled out because in high-risk areas, chemoprophylaxis provides important additional protection beyond bite avoidance alone, and omitting it increases risk.', 2),
('f1000000-0000-0000-0000-000000000028', 'C', $x$A combination of Awareness of risk, Bite prevention, Chemoprophylaxis, and prompt Diagnosis if fever develops (the 'ABCD' approach)$x$, true, 'Correct. Malaria prevention is best achieved through a combined approach: Awareness of risk, Bite prevention (repellents, nets, appropriate clothing), Chemoprophylaxis (appropriate for the destination), and prompt Diagnosis and treatment if fever develops during or after travel; no single measure alone is fully protective.', 3),
('f1000000-0000-0000-0000-000000000028', 'D', 'Vaccination alone as sufficient protection', false, 'Ruled out because although malaria vaccines exist and are being introduced in some contexts, they are not yet a substitute for the standard combined ABCD approach for travellers, particularly adult travellers to endemic areas.', 4),
('f1000000-0000-0000-0000-000000000028', 'E', 'No specific measures needed if staying in urban areas only', false, 'Ruled out because malaria risk, while often lower in some urban centres, can still be present, and specific advice should be tailored to the itinerary rather than assuming urban travel eliminates risk entirely.', 5),
('f1000000-0000-0000-0000-000000000029', 'A', 'Reinfection from a new mosquito bite', false, 'Ruled out because there has been no further travel to an endemic area, making a new mosquito-borne infection implausible; the relapse instead reflects reactivation of the original infection.', 1),
('f1000000-0000-0000-0000-000000000029', 'B', 'Treatment failure due to drug resistance in the original episode', false, 'Ruled out because although resistance can occur, the classic and most likely explanation for a P. vivax relapse months later without further exposure is hypnozoite reactivation, not resistance to the original blood-stage treatment.', 2),
('f1000000-0000-0000-0000-000000000029', 'C', 'Chronic carriage of blood-stage parasites since the original infection', false, 'Ruled out because standard antimalarial treatment clears blood-stage parasitaemia; the relapse mechanism specific to P. vivax and P. ovale is reactivation from the dormant liver stage, not persistence of blood-stage parasites.', 3),
('f1000000-0000-0000-0000-000000000029', 'D', 'Reactivation of dormant liver-stage hypnozoites', true, 'Correct. Plasmodium vivax (and P. ovale) can form dormant liver-stage hypnozoites that reactivate weeks to months (or even years) after the initial infection, causing relapse without any further mosquito exposure; this is why radical cure with a hypnozoite-active drug (e.g. primaquine) is needed in addition to standard blood-stage treatment.', 4),
('f1000000-0000-0000-0000-000000000029', 'E', 'A laboratory error in blood film interpretation', false, 'Ruled out because the clinical presentation (recurrent similar febrile illness with a positive blood film for the same species) is consistent with a recognised biological phenomenon (hypnozoite relapse), not simply a testing error.', 5),
('f1000000-0000-0000-0000-000000000030', 'A', 'Pyogenic liver abscess', false, 'Ruled out because although pyogenic abscess is an important differential for a hepatic lesion with fever, the positive Entamoeba histolytica serology specifically confirms an amoebic, rather than bacterial, cause here.', 1),
('f1000000-0000-0000-0000-000000000030', 'B', 'Hepatocellular carcinoma', false, 'Ruled out because HCC does not typically present acutely with fever and would not be associated with positive amoebic serology; the clinical and serological picture points to an infective, not neoplastic, cause.', 2),
('f1000000-0000-0000-0000-000000000030', 'C', 'Hydatid cyst (Echinococcus)', false, 'Ruled out because hydatid disease is typically associated with a different exposure history (contact with dogs/livestock in endemic sheep-farming regions) and would not show positive Entamoeba histolytica serology.', 3),
('f1000000-0000-0000-0000-000000000030', 'D', 'Acute viral hepatitis', false, 'Ruled out because viral hepatitis typically causes diffuse hepatic inflammation with jaundice and markedly deranged liver enzymes, not a discrete hepatic lesion on imaging with positive amoebic serology.', 4),
('f1000000-0000-0000-0000-000000000030', 'E', 'Amoebic liver abscess', true, 'Correct. Fever, right upper quadrant pain, tender hepatomegaly and a hepatic lesion on imaging, with positive Entamoeba histolytica serology in a returning traveller, is characteristic of amoebic liver abscess, acquired via faecal-oral transmission of the parasite in endemic regions.', 5),
('f1000000-0000-0000-0000-000000000031', 'A', 'Oral vancomycin', true, 'Correct. Oral vancomycin (poorly absorbed systemically, achieving high intraluminal gut concentrations) is first-line treatment for Clostridioides difficile infection, alongside stopping the precipitating antibiotic where possible and implementing infection control measures.', 1),
('f1000000-0000-0000-0000-000000000031', 'B', 'IV vancomycin', false, 'Ruled out because IV vancomycin does not achieve adequate concentrations within the bowel lumen to treat C. difficile colitis; oral administration is required for this indication.', 2),
('f1000000-0000-0000-0000-000000000031', 'C', 'Oral metronidazole as first-line for all severities', false, 'Ruled out because oral vancomycin (or fidaxomicin) is now preferred first-line over metronidazole for C. difficile infection, given superior efficacy demonstrated in trials, with metronidazole reserved for specific circumstances.', 3),
('f1000000-0000-0000-0000-000000000031', 'D', 'Loperamide to control diarrhoea', false, 'Ruled out because anti-motility agents like loperamide are generally avoided in C. difficile infection, as they can worsen toxin retention and increase the risk of complications such as toxic megacolon.', 4),
('f1000000-0000-0000-0000-000000000031', 'E', 'No specific treatment, as symptoms will resolve spontaneously', false, 'Ruled out because C. difficile infection can cause significant morbidity and mortality, particularly in elderly patients, and requires specific antimicrobial treatment rather than watchful waiting.', 5),
('f1000000-0000-0000-0000-000000000032', 'A', 'Simple constipation', false, 'Ruled out because the combination of marked colonic dilatation with systemic toxicity in the context of severe colitis reflects a serious complication (toxic megacolon), not simple constipation.', 1),
('f1000000-0000-0000-0000-000000000032', 'B', 'Irritable bowel syndrome', false, 'Ruled out because IBS is a chronic functional disorder, not an acute, life-threatening complication of severe colitis with systemic toxicity and colonic dilatation.', 2),
('f1000000-0000-0000-0000-000000000032', 'C', 'Toxic megacolon', true, 'Correct. Marked colonic dilatation with systemic toxicity, abdominal distension and absent bowel sounds in a patient with severe C. difficile colitis indicates toxic megacolon, a life-threatening complication requiring urgent surgical assessment alongside intensive medical management, given the risk of perforation.', 3),
('f1000000-0000-0000-0000-000000000032', 'D', 'Normal post-infective ileus without complication', false, 'Ruled out because the degree of colonic dilatation combined with systemic toxicity indicates a significant, dangerous complication requiring urgent intervention, not a benign self-limiting ileus.', 4),
('f1000000-0000-0000-0000-000000000032', 'E', 'Small bowel obstruction', false, 'Ruled out because the clinical and radiological picture described (colonic dilatation in the context of severe colitis) specifically indicates toxic megacolon (a colonic process), not small bowel obstruction.', 5),
('f1000000-0000-0000-0000-000000000033', 'A', 'Systemic IV antibiotics for all colonised patients', false, 'Ruled out because systemic antibiotic treatment is not indicated for asymptomatic colonisation without evidence of active infection; this would risk unnecessary side effects and further antimicrobial resistance.', 1),
('f1000000-0000-0000-0000-000000000033', 'B', 'No action required, as colonisation does not matter', false, 'Ruled out because colonisation carries a risk of transmission to other vulnerable patients and potential progression to infection, so infection control measures and decolonisation are appropriate even without active infection.', 2),
('f1000000-0000-0000-0000-000000000033', 'C', 'Immediate discharge from hospital regardless of clinical need', false, 'Ruled out because MRSA colonisation status alone is not a reason to discharge a patient who still requires inpatient care; infection control measures should be implemented instead.', 3),
('f1000000-0000-0000-0000-000000000033', 'D', 'Topical decolonisation therapy (e.g. nasal mupirocin and chlorhexidine body wash) and contact precautions', true, 'Correct. Asymptomatic MRSA carriers are managed with topical decolonisation therapy to reduce bacterial load and transmission risk, alongside contact precautions (isolation or cohorting, personal protective equipment) to prevent spread to other patients, without requiring systemic antibiotics unless active infection develops.', 4),
('f1000000-0000-0000-0000-000000000033', 'E', 'Oral vancomycin for all colonised patients', false, 'Ruled out because oral vancomycin is used to treat C. difficile colitis, not for MRSA decolonisation, and systemic treatment is not indicated for asymptomatic carriage.', 5),
('f1000000-0000-0000-0000-000000000034', 'A', 'The same narrow-spectrum antibiotic regimen used for community-acquired pneumonia', false, 'Ruled out because hospital-acquired pneumonia carries a different, often more resistant, organism profile than community-acquired pneumonia, requiring a different (typically broader) empirical antibiotic approach.', 1),
('f1000000-0000-0000-0000-000000000034', 'B', 'Broader-spectrum antibiotics covering likely hospital-acquired, potentially more resistant organisms, guided by local hospital antimicrobial policy', true, 'Correct. Hospital-acquired pneumonia (developing more than 48 hours after admission) is more likely than community-acquired pneumonia to involve resistant or hospital-associated organisms (e.g. Gram-negative bacilli, MRSA); empirical antibiotic choice should follow local hospital antimicrobial guidelines, which reflect local resistance patterns, and typically use broader-spectrum cover than for community-acquired pneumonia.', 2),
('f1000000-0000-0000-0000-000000000034', 'C', 'No antibiotics until sputum culture results are available', false, 'Ruled out because delaying antibiotics for culture results in a patient with signs of pneumonia risks clinical deterioration; empirical treatment should start promptly based on likely organisms, with therapy refined once culture results return.', 3),
('f1000000-0000-0000-0000-000000000034', 'D', 'A single dose of oral antibiotics only, regardless of severity', false, 'Ruled out because hospital-acquired pneumonia often requires a full course of appropriately chosen antibiotics (potentially IV depending on severity), not a single oral dose.', 4),
('f1000000-0000-0000-0000-000000000034', 'E', 'Antiviral therapy alone, with no antibacterial cover', false, 'Ruled out because bacterial pathogens are the predominant cause of hospital-acquired pneumonia, and antibacterial (not purely antiviral) treatment is required as the primary approach.', 5),
('f1000000-0000-0000-0000-000000000035', 'A', 'Pulmonary oedema', false, 'Ruled out because pulmonary oedema does not typically cause fever or purulent secretions; these findings specifically point to an infective process.', 1),
('f1000000-0000-0000-0000-000000000035', 'B', 'Pulmonary embolism', false, 'Ruled out because PE does not classically cause fever with purulent tracheal secretions, which are specific indicators of pneumonia rather than a thromboembolic event.', 2),
('f1000000-0000-0000-0000-000000000035', 'C', 'Atelectasis', false, 'Ruled out because atelectasis alone does not cause fever or purulent secretions; these clinical features indicate an infective, not simply mechanical, process.', 3),
('f1000000-0000-0000-0000-000000000035', 'D', 'Aspiration alone without infection', false, 'Ruled out because although aspiration can predispose to VAP, the presence of fever, purulent secretions and a new infiltrate indicates an established infective pneumonia, not simply aspiration without infection.', 4),
('f1000000-0000-0000-0000-000000000035', 'E', 'Ventilator-associated pneumonia', true, 'Correct. New fever, purulent tracheal secretions and a new radiographic infiltrate developing more than 48 hours after initiation of mechanical ventilation is the defining presentation of ventilator-associated pneumonia, a common and significant nosocomial infection in ventilated ICU patients.', 5),
('f1000000-0000-0000-0000-000000000036', 'A', 'Continue normal ward activity with no additional precautions', false, 'Ruled out because failing to implement outbreak control measures would allow continued spread of a highly contagious pathogen to other vulnerable patients and staff.', 1),
('f1000000-0000-0000-0000-000000000036', 'B', 'Closure of the affected ward to new admissions, with enhanced cleaning and isolation of symptomatic patients', true, 'Correct. A rapidly spreading outbreak of vomiting and diarrhoea affecting patients and staff over a short period is highly suggestive of norovirus, which is highly contagious; ward closure to new admissions, cohorting/isolating symptomatic individuals, and enhanced environmental cleaning (norovirus is resistant to standard alcohol gel, requiring soap and water hand hygiene) are key outbreak control measures.', 2),
('f1000000-0000-0000-0000-000000000036', 'C', 'Treat all affected individuals with broad-spectrum antibiotics', false, 'Ruled out because norovirus is a viral infection; antibiotics have no role in its treatment, which is supportive (hydration) alongside infection control measures to limit spread.', 3),
('f1000000-0000-0000-0000-000000000036', 'D', 'Alcohol gel hand sanitiser alone, without other measures', false, 'Ruled out because norovirus is relatively resistant to alcohol-based hand sanitisers; soap and water handwashing is required, alongside broader outbreak control measures such as ward closure and enhanced cleaning.', 4),
('f1000000-0000-0000-0000-000000000036', 'E', 'No action needed until formal laboratory confirmation of norovirus', false, 'Ruled out because outbreak control measures should be implemented promptly based on the clinical pattern, without waiting for laboratory confirmation, to limit ongoing transmission during a rapidly evolving outbreak.', 5),
('f1000000-0000-0000-0000-000000000037', 'A', 'Squeeze the wound vigorously to force out as much blood as possible', false, 'Ruled out because vigorous squeezing is not recommended, as it does not clearly reduce infection risk and may cause additional tissue trauma; gentle encouragement of natural bleeding is advised instead.', 1),
('f1000000-0000-0000-0000-000000000037', 'B', 'Apply a tourniquet above the injury site', false, 'Ruled out because a tourniquet is not part of standard needlestick injury first aid; the priority is bleeding encouragement and thorough washing, not restricting blood flow.', 2),
('f1000000-0000-0000-0000-000000000037', 'C', 'Encourage bleeding from the wound and wash thoroughly with soap and water', true, 'Correct. Immediate first aid after a needlestick injury involves encouraging the wound to bleed (without squeezing or sucking) and washing thoroughly with soap and water, before proceeding to risk assessment, reporting to occupational health, and consideration of post-exposure prophylaxis if indicated.', 3),
('f1000000-0000-0000-0000-000000000037', 'D', 'Ignore the injury if the healthcare worker feels well', false, 'Ruled out because bloodborne virus transmission risk is not related to how the healthcare worker currently feels; proper first aid and risk assessment are required regardless of symptoms.', 4),
('f1000000-0000-0000-0000-000000000037', 'E', 'Apply antiseptic cream only, with no further action', false, 'Ruled out because antiseptic cream alone is insufficient; proper first aid (bleeding, washing) should be followed by formal risk assessment, reporting, and consideration of post-exposure prophylaxis where indicated.', 5),
('f1000000-0000-0000-0000-000000000038', 'A', 'Prophylactic antibiotics for the entire duration of catheterisation', false, 'Ruled out because prophylactic antibiotics are not recommended for the duration of catheterisation, as they do not reliably prevent infection and contribute to antimicrobial resistance.', 1),
('f1000000-0000-0000-0000-000000000038', 'B', 'Routine catheter changes every 24 hours regardless of clinical need', false, 'Ruled out because frequent unnecessary catheter changes do not reduce infection risk and instead introduce additional opportunities for organism introduction; the priority is removing catheters that are no longer needed, not routinely changing them.', 2),
('f1000000-0000-0000-0000-000000000038', 'C', 'Bladder irrigation with antiseptic solution as a routine measure', false, 'Ruled out because routine antiseptic bladder irrigation is not an evidence-based measure for preventing catheter-associated UTI and is not part of standard prevention bundles.', 3),
('f1000000-0000-0000-0000-000000000038', 'D', 'Continuous antibiotic prophylaxis started only if the catheter remains in place for more than a week', false, 'Ruled out because prolonged antibiotic prophylaxis is not the recommended approach; minimising catheter duration through daily review and prompt removal is the evidence-based priority intervention.', 4),
('f1000000-0000-0000-0000-000000000038', 'E', 'Daily review of the ongoing need for the catheter, with prompt removal once no longer indicated', true, 'Correct. Since catheter-associated urinary tract infection risk increases with duration of catheterisation, daily review of ongoing clinical need with prompt removal as soon as the catheter is no longer required is the single most effective measure for reducing catheter-associated UTIs.', 5),
('f1000000-0000-0000-0000-000000000039', 'A', 'Contact precautions, including single-room isolation where possible and dedicated equipment', true, 'Correct. VRE is spread by direct and indirect contact; contact precautions -- single-room isolation where feasible, use of gloves and gowns, and dedicated or thoroughly cleaned equipment -- are the key infection control measures to prevent transmission to other patients, alongside good hand hygiene practices by staff and visitors.', 1),
('f1000000-0000-0000-0000-000000000039', 'B', 'Immediate treatment with vancomycin', false, 'Ruled out because VRE is, by definition, resistant to vancomycin, so this drug would be ineffective; furthermore, asymptomatic colonisation does not require antibiotic treatment at all.', 2),
('f1000000-0000-0000-0000-000000000039', 'C', 'No specific precautions needed as she is asymptomatic', false, 'Ruled out because asymptomatic colonisation still carries a risk of transmission to other vulnerable patients, so contact precautions remain important even without active infection.', 3),
('f1000000-0000-0000-0000-000000000039', 'D', 'Airborne precautions with a negative-pressure room', false, 'Ruled out because VRE is spread by contact, not by an airborne route, so airborne precautions (relevant to pathogens like tuberculosis or measles) are not the appropriate infection control measure here.', 4),
('f1000000-0000-0000-0000-000000000039', 'E', 'Discharge from hospital regardless of ongoing clinical need', false, 'Ruled out because VRE colonisation status alone is not an indication for discharge if the patient still requires inpatient care; appropriate infection control precautions should be implemented instead.', 5),
('f1000000-0000-0000-0000-000000000040', 'A', 'Eliminating all antibiotic use in hospitals', false, 'Ruled out because antibiotics remain essential for treating bacterial infections; the goal of stewardship is appropriate, not eliminated, use.', 1),
('f1000000-0000-0000-0000-000000000040', 'B', 'Ensuring the broadest possible antibiotic is used for every infection', false, 'Ruled out because using unnecessarily broad-spectrum antibiotics increases resistance pressure and side effects; stewardship instead promotes narrow, targeted therapy where appropriate.', 2),
('f1000000-0000-0000-0000-000000000040', 'C', 'Reducing hospital costs as the primary objective, independent of patient outcomes', false, 'Ruled out because although stewardship can have cost benefits, its primary goal is optimising clinical outcomes and combating resistance, not cost reduction as the main driver.', 3),
('f1000000-0000-0000-0000-000000000040', 'D', 'Optimising antibiotic use to improve patient outcomes while minimising the development of antimicrobial resistance', true, 'Correct. Antimicrobial stewardship aims to ensure antibiotics are used appropriately -- the right drug, dose, route and duration for the right indication -- to optimise individual patient outcomes while reducing the selection pressure that drives antimicrobial resistance at a population level.', 4),
('f1000000-0000-0000-0000-000000000040', 'E', 'Increasing the duration of antibiotic courses to ensure complete eradication of all organisms', false, 'Ruled out because stewardship often specifically aims to use the shortest effective duration of therapy supported by evidence, not to lengthen courses unnecessarily.', 5),
('f1000000-0000-0000-0000-000000000041', 'A', 'Proceed with amoxicillin, as the allergy may have resolved over time', false, 'Ruled out because a documented history of anaphylaxis is a serious, high-risk allergy that should not be disregarded without formal allergy testing; proceeding empirically risks a life-threatening reaction.', 1),
('f1000000-0000-0000-0000-000000000041', 'B', 'Withhold amoxicillin and choose a non-beta-lactam alternative', true, 'Correct. A documented history of anaphylaxis to penicillin is an absolute contraindication to amoxicillin (a penicillin) and to other beta-lactams with significant cross-reactivity risk; a non-beta-lactam alternative should be chosen, guided by local antimicrobial policy.', 2),
('f1000000-0000-0000-0000-000000000041', 'C', 'Give amoxicillin alongside prophylactic antihistamines to prevent a reaction', false, 'Ruled out because antihistamine prophylaxis does not reliably prevent anaphylaxis and is not an appropriate strategy for a patient with a documented history of this severe reaction to the same drug class.', 3),
('f1000000-0000-0000-0000-000000000041', 'D', 'Use a cephalosporin instead, assuming no cross-reactivity', false, 'Ruled out because although cross-reactivity rates between penicillins and cephalosporins are lower than once thought, there remains a recognised risk, particularly with earlier-generation cephalosporins, and this should be approached cautiously, ideally with specialist allergy input, rather than assumed to be safe.', 4),
('f1000000-0000-0000-0000-000000000041', 'E', 'Perform a small test dose of amoxicillin under observation', false, 'Ruled out because a graded test dose is not an appropriate approach for a patient with a documented history of anaphylaxis to the same drug; the immediate priority is avoiding the causative agent, not challenge testing outside a specialist allergy service.', 5),
('f1000000-0000-0000-0000-000000000042', 'A', 'Dose adjustment based on renal function with therapeutic drug level monitoring', true, 'Correct. Gentamicin is renally cleared and has a narrow therapeutic window with significant nephrotoxic and ototoxic potential; in renal impairment, the dose and/or dosing interval must be adjusted based on renal function, with therapeutic drug monitoring (trough and/or peak levels) used to guide safe, effective dosing.', 1),
('f1000000-0000-0000-0000-000000000042', 'B', 'No dose adjustment is needed regardless of renal function', false, 'Ruled out because gentamicin accumulates in renal impairment if the dose is not adjusted, significantly increasing the risk of nephrotoxicity and ototoxicity.', 2),
('f1000000-0000-0000-0000-000000000042', 'C', 'Gentamicin should be given as a fixed dose without any monitoring', false, $x$Ruled out because gentamicin's narrow therapeutic index necessitates level monitoring, particularly in patients with renal impairment, to avoid toxicity while ensuring efficacy.$x$, 3),
('f1000000-0000-0000-0000-000000000042', 'D', 'Switch to a higher initial dose to compensate for reduced clearance', false, 'Ruled out because reduced renal clearance means the drug will accumulate; the dose (or interval) should be reduced/extended, not increased, in this context.', 4),
('f1000000-0000-0000-0000-000000000042', 'E', 'Oral gentamicin is preferred over IV in renal impairment', false, 'Ruled out because gentamicin is not effectively absorbed orally for treating systemic infections; it is administered parenterally, and the key consideration remains appropriate IV dose adjustment and monitoring.', 5),
('f1000000-0000-0000-0000-000000000043', 'A', 'Nitrofurantoin', false, 'Ruled out because nitrofurantoin does not have a well-established, clinically significant interaction with warfarin metabolism in the way trimethoprim does.', 1),
('f1000000-0000-0000-0000-000000000043', 'B', 'Amoxicillin', false, 'Ruled out because although amoxicillin can occasionally alter gut flora affecting vitamin K synthesis, it does not have as strong or well-recognised an interaction with warfarin as trimethoprim.', 2),
('f1000000-0000-0000-0000-000000000043', 'C', 'Cefalexin', false, 'Ruled out because cefalexin does not have a well-established significant interaction with warfarin metabolism in the way trimethoprim does.', 3),
('f1000000-0000-0000-0000-000000000043', 'D', 'Doxycycline', false, 'Ruled out because doxycycline is not typically used for uncomplicated UTI and does not have the same well-recognised, significant warfarin interaction as trimethoprim.', 4),
('f1000000-0000-0000-0000-000000000043', 'E', 'Trimethoprim', true, 'Correct. Trimethoprim (commonly used for UTIs) is a recognised inhibitor of warfarin metabolism, significantly potentiating its anticoagulant effect and raising INR, increasing bleeding risk; this interaction requires close INR monitoring or use of an alternative antibiotic where possible.', 5),
('f1000000-0000-0000-0000-000000000044', 'A', 'Simple overuse injury unrelated to medication', false, 'Ruled out because the temporal relationship to starting a fluoroquinolone and the specific, well-recognised association with tendon rupture make a drug-related cause far more likely than coincidental overuse injury.', 1),
('f1000000-0000-0000-0000-000000000044', 'B', 'Gout affecting the Achilles tendon region', false, 'Ruled out because gout classically affects joints (e.g. first metatarsophalangeal joint) with associated inflammation and hyperuricaemia, not a specific tendon rupture pattern linked to recent fluoroquinolone use.', 2),
('f1000000-0000-0000-0000-000000000044', 'C', 'Cellulitis of the lower leg', false, 'Ruled out because cellulitis would present with spreading erythema, warmth and systemic signs of infection, not the specific pattern of sudden tendon pain/swelling linked temporally to fluoroquinolone therapy.', 3),
('f1000000-0000-0000-0000-000000000044', 'D', 'Fluoroquinolone-associated tendinopathy/tendon rupture', true, 'Correct. Fluoroquinolones (e.g. ciprofloxacin) carry a recognised risk of tendinopathy and tendon rupture, particularly affecting the Achilles tendon, with risk increased in older patients and those on concurrent corticosteroids; the drug should be stopped immediately and the patient advised to rest the affected limb.', 4),
('f1000000-0000-0000-0000-000000000044', 'E', 'Deep vein thrombosis', false, 'Ruled out because DVT typically causes diffuse calf swelling and tenderness rather than localised tendon pain, and does not have the specific drug association described here.', 5),
('f1000000-0000-0000-0000-000000000045', 'A', 'Nitrofurantoin (at term, avoided; earlier in pregnancy generally considered acceptable if no alternative)', false, $x$Ruled out as the answer to avoid at this specific early stage, because although nitrofurantoin is generally avoided close to term due to a theoretical risk of neonatal haemolysis, it is more commonly used earlier in pregnancy than trimethoprim, which carries a specific first-trimester teratogenic risk relevant to this patient's gestation.$x$, 1),
('f1000000-0000-0000-0000-000000000045', 'B', 'Amoxicillin (if the organism is sensitive)', false, 'Ruled out because penicillins such as amoxicillin are generally considered safe throughout pregnancy when the causative organism is sensitive, unlike trimethoprim in the first trimester.', 2),
('f1000000-0000-0000-0000-000000000045', 'C', 'Trimethoprim', true, 'Correct. Trimethoprim is a folate antagonist and should be avoided in the first trimester of pregnancy due to an increased risk of neural tube defects, making it an inappropriate choice at 8 weeks gestation.', 3),
('f1000000-0000-0000-0000-000000000045', 'D', 'Cefalexin', false, $x$Ruled out because cephalosporins such as cefalexin are generally considered safe for use in pregnancy, in contrast to trimethoprim's specific first-trimester risk.$x$, 4),
('f1000000-0000-0000-0000-000000000045', 'E', 'Fosfomycin (as a single dose, generally considered an option in pregnancy)', false, 'Ruled out because fosfomycin is generally considered a reasonable option in pregnancy where indicated, unlike trimethoprim, which carries a specific teratogenic risk in the first trimester.', 5),
('f1000000-0000-0000-0000-000000000046', 'A', 'Amoxicillin', true, 'Correct. For low-to-moderate severity community-acquired pneumonia (CURB-65 0-1) in a patient without penicillin allergy, amoxicillin is the standard first-line oral antibiotic choice, targeting the most common causative organism, Streptococcus pneumoniae.', 1),
('f1000000-0000-0000-0000-000000000046', 'B', 'IV meropenem', false, 'Ruled out because a broad-spectrum carbapenem is disproportionately broad for low-severity community-acquired pneumonia and is reserved for more complex or resistant infections, not first-line uncomplicated CAP.', 2),
('f1000000-0000-0000-0000-000000000046', 'C', 'Oral vancomycin', false, 'Ruled out because oral vancomycin is used for C. difficile colitis (acting locally in the gut lumen) and is not absorbed systemically, making it entirely inappropriate for treating pneumonia.', 3),
('f1000000-0000-0000-0000-000000000046', 'D', 'IV gentamicin monotherapy', false, 'Ruled out because gentamicin does not provide reliable cover against the typical pathogens of community-acquired pneumonia (particularly Streptococcus pneumoniae) and is not standard first-line therapy for this indication.', 4),
('f1000000-0000-0000-0000-000000000046', 'E', 'No antibiotics, supportive care only', false, 'Ruled out because bacterial community-acquired pneumonia requires antibiotic treatment; supportive care alone is insufficient even for lower-severity disease.', 5),
('f1000000-0000-0000-0000-000000000047', 'A', 'Dairy products, due to reduced drug absorption', false, 'Ruled out because this interaction is characteristic of tetracyclines (which chelate with calcium), not metronidazole, which does not have this specific dairy interaction.', 1),
('f1000000-0000-0000-0000-000000000047', 'B', 'Alcohol, due to a disulfiram-like reaction', true, 'Correct. Metronidazole inhibits aldehyde dehydrogenase, causing accumulation of acetaldehyde if alcohol is consumed, producing a disulfiram-like reaction (flushing, nausea, vomiting, palpitations, headache); patients should be advised to avoid alcohol during treatment and for 48 hours after finishing the course.', 2),
('f1000000-0000-0000-0000-000000000047', 'C', 'Grapefruit juice, due to CYP3A4 inhibition', false, 'Ruled out because the grapefruit-CYP3A4 interaction is relevant to certain other drug classes (e.g. some statins, calcium channel blockers), not the well-known metronidazole-alcohol interaction being tested here.', 3),
('f1000000-0000-0000-0000-000000000047', 'D', 'Sunlight exposure, due to photosensitivity', false, 'Ruled out because photosensitivity is a recognised side effect of other antibiotics (e.g. tetracyclines, fluoroquinolones), not the specific, classic interaction associated with metronidazole.', 4),
('f1000000-0000-0000-0000-000000000047', 'E', 'Calcium supplements, due to chelation', false, 'Ruled out because chelation with divalent cations is characteristic of tetracyclines and fluoroquinolones, not the specific alcohol interaction relevant to metronidazole.', 5),
('f1000000-0000-0000-0000-000000000048', 'A', 'Increased phenytoin levels leading to toxicity', false, 'Ruled out because rifampicin induces (rather than inhibits) the relevant metabolic enzymes, which would lower, not raise, phenytoin levels.', 1),
('f1000000-0000-0000-0000-000000000048', 'B', 'No effect on phenytoin levels', false, $x$Ruled out because rifampicin's enzyme-inducing effect is well established and clinically significant, meaning a real interaction should be anticipated and monitored for, not assumed to be absent.$x$, 2),
('f1000000-0000-0000-0000-000000000048', 'C', 'Reduced phenytoin levels due to hepatic enzyme induction, risking loss of seizure control', true, 'Correct. Rifampicin is a potent inducer of hepatic cytochrome P450 enzymes, which increases the metabolism (and therefore reduces plasma levels) of many co-administered drugs, including phenytoin; this can result in loss of seizure control unless the phenytoin dose is adjusted and levels are monitored.', 3),
('f1000000-0000-0000-0000-000000000048', 'D', 'Phenytoin will reduce the effectiveness of rifampicin instead', false, $x$Ruled out because although phenytoin can have some enzyme-inducing properties itself, the clinically dominant and well-recognised effect in this combination is rifampicin's induction lowering phenytoin levels, which is the relevant safety concern here.$x$, 4),
('f1000000-0000-0000-0000-000000000048', 'E', 'The interaction only becomes relevant after several months of concurrent treatment', false, 'Ruled out because enzyme induction from rifampicin begins within days of starting treatment and can meaningfully affect phenytoin levels well before several months have passed, requiring monitoring from early in co-administration.', 5),
('f1000000-0000-0000-0000-000000000049', 'A', 'Anaphylaxis to vancomycin requiring permanent avoidance of the drug', false, 'Ruled out because red man syndrome is a rate-related, non-IgE-mediated reaction, not true anaphylaxis, and does not necessarily require permanent avoidance of vancomycin; slowing the infusion rate often allows continued safe use.', 1),
('f1000000-0000-0000-0000-000000000049', 'B', 'Nephrotoxicity from vancomycin', false, 'Ruled out because nephrotoxicity presents with rising creatinine and reduced urine output over time, not the acute flushing, rash and hypotension temporally linked to rapid infusion described here.', 2),
('f1000000-0000-0000-0000-000000000049', 'C', 'Ototoxicity from vancomycin', false, 'Ruled out because ototoxicity presents with hearing loss or tinnitus, not the acute infusion-related flushing and hypotension described.', 3),
('f1000000-0000-0000-0000-000000000049', 'D', $x$Vancomycin infusion reaction ('red man syndrome')$x$, true, $x$Correct. Rapid vancomycin infusion can cause direct mast cell degranulation and histamine release, producing flushing, an erythematous rash (classically over the face, neck and upper torso) and hypotension -- 'red man syndrome' -- which is managed by slowing the infusion rate and, if needed, giving antihistamines, and is not a true IgE-mediated allergy.$x$, 4),
('f1000000-0000-0000-0000-000000000049', 'E', 'Unrelated viral exanthem', false, 'Ruled out because the clear temporal relationship to a rapid vancomycin infusion, with the classic distribution and associated hypotension, is much more consistent with a recognised infusion reaction than a coincidental viral rash.', 5),
('f1000000-0000-0000-0000-000000000050', 'A', 'Amoxicillin should still be used, as it is a commonly prescribed antibiotic', false, 'Ruled out because the organism is specifically reported as resistant to amoxicillin, meaning it would not be effective treatment despite being commonly prescribed for other indications.', 1),
('f1000000-0000-0000-0000-000000000050', 'B', 'Co-amoxiclav should always be preferred over narrower agents once sensitivity is confirmed', false, 'Ruled out because when a narrower-spectrum agent (such as nitrofurantoin or trimethoprim) is also effective, it is preferred over broader-spectrum options like co-amoxiclav, consistent with antimicrobial stewardship principles of using the narrowest effective therapy.', 2),
('f1000000-0000-0000-0000-000000000050', 'C', 'Sensitivity results are not relevant once empirical treatment has started', false, 'Ruled out because sensitivity results are specifically used to review and refine initial empirical treatment, ensuring the chosen antibiotic will actually be effective against the identified organism.', 3),
('f1000000-0000-0000-0000-000000000050', 'D', 'No antibiotic is needed once sensitivities are known', false, 'Ruled out because a positive culture with a symptomatic urinary infection still requires antibiotic treatment; the sensitivity results guide which antibiotic to use, not whether treatment is needed at all.', 4),
('f1000000-0000-0000-0000-000000000050', 'E', 'Treatment should be guided by the reported sensitivities, choosing an antibiotic the organism is sensitive to, such as nitrofurantoin or trimethoprim', true, $x$Correct. Once culture and sensitivity results are available, antibiotic choice should be refined (de-escalated or adjusted) based on the specific organism's sensitivity pattern, selecting an effective, appropriately narrow-spectrum agent (such as nitrofurantoin or trimethoprim here) rather than continuing an ineffective or unnecessarily broad empirical choice.$x$, 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f1000000-0000-0000-0000-000000000001', 'Hypotension and raised lactate in the context of infection define sepsis with organ dysfunction, mandating urgent, bundled treatment.', 1),
('f1000000-0000-0000-0000-000000000001', 'The Sepsis Six bundle (three tests, three treatments) delivered within one hour is associated with significantly reduced mortality when applied promptly.', 2),
('f1000000-0000-0000-0000-000000000001', 'A recent urinary catheter is a plausible and important source to identify and address (e.g. catheter review/removal) alongside broad-spectrum antibiotic therapy.', 3),
('f1000000-0000-0000-0000-000000000002', 'Persistent hypotension despite adequate fluid resuscitation (typically 30 mL/kg) defines septic shock and signals the need for vasopressor support.', 1),
('f1000000-0000-0000-0000-000000000002', 'Noradrenaline is the first-line vasopressor in septic shock, acting to restore vascular tone and mean arterial pressure.', 2),
('f1000000-0000-0000-0000-000000000002', 'Septic shock management requires escalation to a critical care setting for invasive monitoring and titration of vasopressor therapy.', 3),
('f1000000-0000-0000-0000-000000000003', 'A new regurgitant murmur combined with positive blood cultures and an echocardiographic vegetation fulfils major criteria for infective endocarditis.', 1),
('f1000000-0000-0000-0000-000000000003', 'Intravenous drug use is a classic risk factor specifically for right-sided (tricuspid) endocarditis, differing from the left-sided predominance seen with other risk factors.', 2),
('f1000000-0000-0000-0000-000000000003', 'Staphylococcus aureus is a common and particularly virulent causative organism, associated with a more acute, aggressive clinical course than viridans streptococci.', 3),
('f1000000-0000-0000-0000-000000000004', 'The two major Duke criteria are positive blood cultures with a typical organism and evidence of endocardial involvement (vegetation, abscess, new valvular regurgitation) on echocardiography.', 1),
('f1000000-0000-0000-0000-000000000004', $x$Minor criteria include predisposing heart condition or IV drug use, fever, vascular phenomena (e.g. splinter haemorrhages, Janeway lesions), immunological phenomena (e.g. Osler's nodes, Roth spots, glomerulonephritis), and microbiological evidence not meeting major criteria.$x$, 2),
('f1000000-0000-0000-0000-000000000004', 'A definite diagnosis of infective endocarditis requires either two major criteria, one major plus three minor, or five minor criteria, guiding how findings like splinter haemorrhages contribute to, but do not alone establish, the diagnosis.', 3),
('f1000000-0000-0000-0000-000000000005', 'Refractory septic shock (persistent hypotension despite adequate fluids and escalating vasopressors) is the specific context in which corticosteroid therapy is considered.', 1),
('f1000000-0000-0000-0000-000000000005', 'Critical illness-related corticosteroid insufficiency can impair the normal physiological cortisol surge needed to maintain vascular tone during severe sepsis.', 2),
('f1000000-0000-0000-0000-000000000005', 'Hydrocortisone is an adjunct to, not a replacement for, ongoing source control, antibiotics, fluids and vasopressor therapy in managing septic shock.', 3),
('f1000000-0000-0000-0000-000000000006', 'Asplenia (surgical or functional) is a specific, well-recognised risk factor for fulminant sepsis with encapsulated organisms, due to loss of splenic opsonisation and phagocytic clearance.', 1),
('f1000000-0000-0000-0000-000000000006', 'The classic organisms responsible (Streptococcus pneumoniae, Haemophilus influenzae, Neisseria meningitidis) are the same ones targeted by vaccination programmes recommended for asplenic patients.', 2),
('f1000000-0000-0000-0000-000000000006', 'Rapid, dramatic deterioration over hours (rather than days) is characteristic of OPSI, distinguishing it from more indolent presentations of infection and reinforcing the need for immediate empirical antibiotics and emergency assessment.', 3),
('f1000000-0000-0000-0000-000000000007', 'A rapidly spreading non-blanching purpuric rash with fever and shock is highly specific for meningococcal septicaemia, a rapidly fatal condition without prompt treatment.', 1),
('f1000000-0000-0000-0000-000000000007', 'Empirical antibiotics must be given immediately on clinical suspicion, without waiting for microbiological confirmation, given the speed of deterioration in meningococcal disease.', 2),
('f1000000-0000-0000-0000-000000000007', 'Ceftriaxone is chosen for its broad coverage including Neisseria meningitidis and good CNS penetration, relevant given the frequent concurrent meningitis in this condition.', 3),
('f1000000-0000-0000-0000-000000000008', 'An ascitic fluid neutrophil count above 250 cells/microlitre is the diagnostic threshold for spontaneous bacterial peritonitis, regardless of whether ascitic fluid culture is positive.', 1),
('f1000000-0000-0000-0000-000000000008', 'SBP typically involves a single organism (often gut-derived, e.g. E. coli), in contrast to the polymicrobial picture and much higher cell counts typical of secondary peritonitis from a perforated viscus.', 2),
('f1000000-0000-0000-0000-000000000008', 'Prompt recognition and treatment (empirical antibiotics, e.g. IV cefotaxime) is essential, as SBP carries significant mortality in cirrhotic patients and can precipitate hepatorenal syndrome.', 3),
('f1000000-0000-0000-0000-000000000009', 'A differential time to positivity of two hours or more (catheter sample turning positive earlier than a paired peripheral sample) is a validated, catheter-sparing method for diagnosing catheter-related bloodstream infection.', 1),
('f1000000-0000-0000-0000-000000000009', 'Coagulase-negative staphylococci are common skin commensals and a frequent cause of catheter-related infection, reflecting organisms introduced at the insertion site or during line access.', 2),
('f1000000-0000-0000-0000-000000000009', 'Confirming a catheter-related source (rather than an alternative focus) guides management decisions about whether the line can be salvaged with antibiotic lock therapy or must be removed.', 3),
('f1000000-0000-0000-0000-000000000010', 'Growth of a recognised pathogen (rather than a typical skin commensal) from blood cultures is more likely to represent true infection than contamination.', 1),
('f1000000-0000-0000-0000-000000000010', 'Concordant growth from two separately drawn culture sets strengthens confidence that a positive result reflects true bacteraemia rather than a single contaminated sample.', 2),
('f1000000-0000-0000-0000-000000000010', 'Confirmed bacteraemia should prompt a search for the underlying source (e.g. urinary, biliary, line-related) to guide both antibiotic choice and duration, and any necessary source control.', 3),
('f1000000-0000-0000-0000-000000000011', 'A CD4 count below 200 cells/microlitre defines the threshold at which PCP risk rises significantly, making CD4 count a key contextual clue.', 1),
('f1000000-0000-0000-0000-000000000011', 'Marked oxygen desaturation on exertion, disproportionate to resting symptoms, is a characteristic and diagnostically useful feature of PCP.', 2),
('f1000000-0000-0000-0000-000000000011', 'Bilateral, perihilar, interstitial (rather than focal lobar) infiltrates on chest X-ray are typical of PCP, distinguishing it from typical bacterial pneumonia.', 3),
('f1000000-0000-0000-0000-000000000012', 'A very low CD4 count (typically below 100 cells/microlitre) is the classic context for cryptococcal meningitis in HIV.', 1),
('f1000000-0000-0000-0000-000000000012', 'A markedly raised CSF opening pressure is a characteristic and clinically important feature of cryptococcal meningitis, often requiring therapeutic lumbar puncture to manage.', 2),
('f1000000-0000-0000-0000-000000000012', 'A positive India ink stain, demonstrating the encapsulated yeast Cryptococcus neoformans, provides rapid bedside diagnostic confirmation.', 3),
('f1000000-0000-0000-0000-000000000013', 'Multiple (rather than single) ring-enhancing lesions favour toxoplasmosis over primary CNS lymphoma, which more often presents as a solitary lesion.', 1),
('f1000000-0000-0000-0000-000000000013', 'A CD4 count below 100-150 cells/microlitre is the typical threshold at which toxoplasma reactivation risk rises significantly.', 2),
('f1000000-0000-0000-0000-000000000013', 'Empirical anti-toxoplasma treatment (e.g. pyrimethamine-sulfadiazine) with clinical and radiological reassessment is the standard initial approach, reserving brain biopsy for cases failing to respond, given the risks of biopsy in this population.', 3),
('f1000000-0000-0000-0000-000000000014', 'White plaques on oesophageal endoscopy are a classic and fairly specific finding for Candida oesophagitis.', 1),
('f1000000-0000-0000-0000-000000000014', 'A CD4 count below 200 cells/microlitre is the typical threshold at which oesophageal candidiasis risk rises significantly, and its presence is itself an AIDS-defining illness.', 2),
('f1000000-0000-0000-0000-000000000014', 'Response to empirical antifungal therapy (e.g. fluconazole) both treats the condition and supports the diagnosis, reserving endoscopy with biopsy for cases failing to respond.', 3),
('f1000000-0000-0000-0000-000000000015', 'Onset within days to weeks of starting antiretroviral therapy, in a patient starting treatment with a low CD4 count, is the classic temporal pattern for IRIS.', 1),
('f1000000-0000-0000-0000-000000000015', 'Improving immunological markers (rising CD4, falling viral load) alongside paradoxical clinical worsening is the key distinguishing feature from treatment failure or disease progression.', 2),
('f1000000-0000-0000-0000-000000000015', 'IRIS reflects an exaggerated inflammatory response to a pre-existing (often previously subclinical) pathogen as immune function recovers, rather than a new infective process.', 3),
('f1000000-0000-0000-0000-000000000016', 'Maternal viral load at the time of delivery is the single strongest predictor of mother-to-child transmission risk, making viral suppression through ART the cornerstone of prevention.', 1),
('f1000000-0000-0000-0000-000000000016', 'With a well-suppressed viral load, transmission risk is very low regardless of delivery mode, whereas an unsuppressed viral load near delivery may prompt consideration of elective caesarean section and additional interventions.', 2),
('f1000000-0000-0000-0000-000000000016', 'Postnatal interventions (neonatal prophylaxis, infant feeding choices) provide additional risk reduction but are secondary to achieving maternal viral suppression throughout pregnancy.', 3),
('f1000000-0000-0000-0000-000000000017', 'PEP is most effective the sooner it is started after exposure, with a defined window (typically up to 72 hours) beyond which efficacy is not established.', 1),
('f1000000-0000-0000-0000-000000000017', 'A 28-day course of combination antiretroviral therapy is the standard PEP regimen, distinct from long-term PrEP used for ongoing risk reduction.', 2),
('f1000000-0000-0000-0000-000000000017', 'PEP should not be delayed pending HIV testing of the source or recipient, given the time-sensitive nature of its effectiveness.', 3),
('f1000000-0000-0000-0000-000000000018', 'A CD4 count below 50 cells/microlitre is the classic threshold at which disseminated MAC infection risk rises significantly.', 1),
('f1000000-0000-0000-0000-000000000018', 'Positive blood cultures growing Mycobacterium avium complex provide direct microbiological confirmation, distinguishing it from other causes of systemic symptoms and diarrhoea in advanced HIV.', 2),
('f1000000-0000-0000-0000-000000000018', 'Chronic, non-specific systemic symptoms (fever, weight loss, night sweats, diarrhoea) in a patient with very advanced immunosuppression should prompt blood cultures with mycobacterial culture bottles to identify this and other disseminated infections.', 3),
('f1000000-0000-0000-0000-000000000019', 'Chronic immune activation and inflammation persist to some degree even with effective viral suppression, contributing to accelerated atherosclerosis and cardiovascular risk.', 1),
('f1000000-0000-0000-0000-000000000019', 'Certain antiretroviral drug classes have been associated with metabolic effects (e.g. dyslipidaemia) that can further contribute to cardiovascular risk.', 2),
('f1000000-0000-0000-0000-000000000019', 'This increased cardiovascular risk means routine HIV care should include proactive assessment and management of traditional cardiovascular risk factors, not just virological monitoring.', 3),
('f1000000-0000-0000-0000-000000000020', 'CD4 count reflects the degree of immune compromise and is used to guide opportunistic infection prophylaxis decisions (e.g. PCP prophylaxis below a certain threshold).', 1),
('f1000000-0000-0000-0000-000000000020', 'Viral load reflects how effectively antiretroviral therapy is suppressing HIV replication, with an undetectable viral load being the treatment goal.', 2),
('f1000000-0000-0000-0000-000000000020', 'Together, these two tests -- rather than general inflammatory or organ function markers -- provide the specific, disease-relevant information needed to guide HIV management decisions.', 3),
('f1000000-0000-0000-0000-000000000021', 'Travel to sub-Saharan Africa carries the highest risk of P. falciparum malaria, the species responsible for the majority of severe and fatal cases.', 1),
('f1000000-0000-0000-0000-000000000021', 'Ring forms on a thick and thin blood film are the classic microscopic finding confirming malaria parasitaemia and allowing species identification and quantification.', 2),
('f1000000-0000-0000-0000-000000000021', 'The percentage parasitaemia (here 1.5%) is an important prognostic marker helping determine disease severity and whether the patient meets criteria for severe malaria requiring more intensive treatment.', 3),
('f1000000-0000-0000-0000-000000000022', 'Features such as parasitaemia above 2%, impaired consciousness, hypoglycaemia, and acute kidney injury define severe malaria, distinguishing it from uncomplicated disease and mandating urgent parenteral treatment.', 1),
('f1000000-0000-0000-0000-000000000022', 'IV artesunate is now the treatment of choice for severe falciparum malaria, having demonstrated a significant mortality benefit over IV quinine in large trials.', 2),
('f1000000-0000-0000-0000-000000000022', 'Severe malaria requires close monitoring and supportive management of complications (hypoglycaemia, renal impairment, cerebral malaria) alongside specific antimalarial therapy.', 3),
('f1000000-0000-0000-0000-000000000023', 'Severe retro-orbital headache is a classically described, relatively specific symptom of dengue fever.', 1),
('f1000000-0000-0000-0000-000000000023', 'Thrombocytopenia with bleeding tendency (bruising, epistaxis) reflects the capillary leak and platelet effects of dengue, and its progression should be monitored closely for warning signs of severe dengue.', 2),
('f1000000-0000-0000-0000-000000000023', 'Travel to a dengue-endemic region (Southeast Asia, South Asia, parts of South America) is an essential contextual clue supporting the diagnosis.', 3),
('f1000000-0000-0000-0000-000000000024', 'A gradually stepwise-rising fever over several days is a classic pattern described in typhoid fever, differing from the abrupt onset of many other tropical fevers.', 1),
('f1000000-0000-0000-0000-000000000024', 'Relative bradycardia (a pulse rate lower than expected for the degree of fever) is a specific, though not universal, clinical sign associated with typhoid.', 2),
('f1000000-0000-0000-0000-000000000024', 'Rose spots (faint salmon-coloured macules, typically on the trunk) are a classically described, though inconsistently present, cutaneous finding in typhoid fever.', 3),
('f1000000-0000-0000-0000-000000000025', 'Itchy skin nodules containing adult worms, combined with progressive visual impairment, are the classic presentation of onchocerciasis.', 1),
('f1000000-0000-0000-0000-000000000025', 'Microfilariae demonstrated on skin snips (rather than blood film, used for other filarial infections) is the specific diagnostic test for onchocerciasis.', 2),
('f1000000-0000-0000-0000-000000000025', $x$Transmission by blackflies breeding near fast-flowing rivers explains the geographic clustering of disease and the name 'river blindness.'$x$, 3),
('f1000000-0000-0000-0000-000000000026', 'Freshwater exposure (swimming, wading) in an endemic region (sub-Saharan Africa for S. haematobium) is the key epidemiological clue, as infection occurs via skin penetration by cercariae in contaminated water.', 1),
('f1000000-0000-0000-0000-000000000026', 'Terminal-spined ova on urine microscopy specifically identify Schistosoma haematobium, distinguishing it from S. mansoni (lateral-spined ova, causing intestinal/hepatic disease).', 2),
('f1000000-0000-0000-0000-000000000026', 'Chronic, untreated urinary schistosomiasis is a recognised risk factor for bladder squamous cell carcinoma, underscoring the importance of diagnosis and treatment.', 3),
('f1000000-0000-0000-0000-000000000027', 'Exposure to floodwater or freshwater potentially contaminated with animal urine is the classic epidemiological risk factor for leptospirosis.', 1),
('f1000000-0000-0000-0000-000000000027', 'Conjunctival suffusion (redness without purulent discharge) is a distinctive and relatively specific clinical sign of leptospirosis.', 2),
('f1000000-0000-0000-0000-000000000027', $x$Severe leptospirosis (Weil's disease) is characterised by the combination of jaundice, acute kidney injury and haemorrhage, reflecting multi-organ involvement in advanced disease.$x$, 3),
('f1000000-0000-0000-0000-000000000028', $x$The 'ABCD' framework emphasises that no single intervention is fully protective; bite avoidance and chemoprophylaxis work together to reduce risk.$x$, 1),
('f1000000-0000-0000-0000-000000000028', 'Prompt diagnosis and treatment of any fever occurring during travel or up to a year after return (given the potential for delayed presentation, e.g. with P. vivax or P. ovale) is a critical final safety net.', 2),
('f1000000-0000-0000-0000-000000000028', 'Chemoprophylaxis choice is tailored to the specific destination based on local resistance patterns, individual risk factors, and drug interactions/contraindications.', 3),
('f1000000-0000-0000-0000-000000000029', 'P. vivax and P. ovale are unique among the malaria species in forming dormant hypnozoites in the liver, which can reactivate months to years after the initial infection.', 1),
('f1000000-0000-0000-0000-000000000029', 'Standard blood-stage antimalarial treatment (e.g. chloroquine or ACT) does not eliminate liver-stage hypnozoites, which is why relapse can occur despite adequate initial treatment.', 2),
('f1000000-0000-0000-0000-000000000029', 'Radical cure with primaquine (or tafenoquine), which specifically targets liver-stage hypnozoites, is required in addition to blood-stage treatment to prevent future relapses (after screening for G6PD deficiency, given the risk of haemolysis).', 3),
('f1000000-0000-0000-0000-000000000030', 'Positive Entamoeba histolytica serology provides specific confirmation of an amoebic cause, distinguishing it from pyogenic or other causes of a hepatic lesion.', 1),
('f1000000-0000-0000-0000-000000000030', 'A single, well-defined hepatic lesion with fever and tender hepatomegaly following travel to an endemic region (with likely faecal-oral exposure) is the classic presentation of amoebic liver abscess.', 2),
('f1000000-0000-0000-0000-000000000030', 'Amoebic liver abscess typically responds well to metronidazole, with drainage reserved for large abscesses or those at risk of rupture, distinguishing management from pyogenic abscess, which more routinely requires drainage alongside antibiotics.', 3),
('f1000000-0000-0000-0000-000000000031', 'Antibiotic exposure (particularly broad-spectrum agents like co-amoxiclav) disrupting normal gut flora is the classic precipitant for C. difficile infection.', 1),
('f1000000-0000-0000-0000-000000000031', 'Oral (not IV) vancomycin is required because the drug needs to act locally within the bowel lumen, where it is poorly absorbed systemically.', 2),
('f1000000-0000-0000-0000-000000000031', 'Anti-motility agents are avoided as they can worsen the condition by delaying clearance of toxin, increasing the risk of severe complications.', 3),
('f1000000-0000-0000-0000-000000000032', 'Toxic megacolon is a recognised, life-threatening complication of severe C. difficile colitis, characterised by colonic dilatation with systemic toxicity.', 1),
('f1000000-0000-0000-0000-000000000032', 'Absent bowel sounds and abdominal distension reflect loss of normal colonic motility as the bowel wall becomes severely inflamed and dilated.', 2),
('f1000000-0000-0000-0000-000000000032', 'Urgent surgical assessment is required given the significant risk of colonic perforation, which carries high mortality if it occurs.', 3),
('f1000000-0000-0000-0000-000000000033', 'Distinguishing colonisation (bacteria present without causing infection) from active infection is essential, as management differs significantly -- decolonisation and infection control versus targeted antibiotic treatment.', 1),
('f1000000-0000-0000-0000-000000000033', $x$Topical decolonisation regimens aim to reduce the bacterial burden and onward transmission risk, rather than to 'treat' an infection that is not present.$x$, 2),
('f1000000-0000-0000-0000-000000000033', 'Contact precautions are a key infection control measure to prevent MRSA spread to other patients in a healthcare setting, particularly relevant in shared bay or ward environments.', 3),
('f1000000-0000-0000-0000-000000000034', 'Hospital-acquired pneumonia, defined as onset more than 48 hours after admission, is associated with a different and often more resistant organism profile than community-acquired pneumonia.', 1),
('f1000000-0000-0000-0000-000000000034', 'Local antimicrobial policies are specifically designed to reflect local resistance patterns and should guide empirical antibiotic choice in the hospital setting.', 2),
('f1000000-0000-0000-0000-000000000034', 'Prompt empirical treatment, refined once culture and sensitivity results are available, balances the need for timely treatment against the risk of unnecessarily broad-spectrum antibiotic use.', 3),
('f1000000-0000-0000-0000-000000000035', 'Onset more than 48 hours after starting mechanical ventilation is the defining temporal criterion for ventilator-associated pneumonia.', 1),
('f1000000-0000-0000-0000-000000000035', 'The combination of fever, purulent secretions and a new radiographic infiltrate together (rather than any single finding alone) supports the diagnosis.', 2),
('f1000000-0000-0000-0000-000000000035', 'VAP prevention bundles (e.g. head-of-bed elevation, sedation holds, oral hygiene) are used in ICU practice specifically to reduce this common and serious complication of mechanical ventilation.', 3),
('f1000000-0000-0000-0000-000000000036', 'A short incubation period with rapid, widespread onset of vomiting and diarrhoea affecting both patients and staff is a classic pattern for norovirus outbreaks in healthcare settings.', 1),
('f1000000-0000-0000-0000-000000000036', 'Norovirus is notably resistant to alcohol-based hand sanitisers, meaning soap and water handwashing is specifically required as part of outbreak control.', 2),
('f1000000-0000-0000-0000-000000000036', 'Prompt implementation of outbreak control measures (isolation, ward closure, enhanced cleaning) should not wait for laboratory confirmation, given the speed of norovirus transmission.', 3),
('f1000000-0000-0000-0000-000000000037', 'Encouraging natural bleeding (rather than squeezing) and washing with soap and water are the recommended immediate first aid steps after a needlestick injury.', 1),
('f1000000-0000-0000-0000-000000000037', 'This should be followed promptly by reporting to occupational health for formal risk assessment, source patient testing where possible, and consideration of post-exposure prophylaxis for HIV and hepatitis B as appropriate.', 2),
('f1000000-0000-0000-0000-000000000037', 'Prompt action is important because the effectiveness of interventions such as HIV PEP diminishes with time since exposure.', 3),
('f1000000-0000-0000-0000-000000000038', 'Duration of catheterisation is the single strongest risk factor for catheter-associated UTI, making minimising unnecessary catheter time the most impactful preventive measure.', 1),
('f1000000-0000-0000-0000-000000000038', 'Daily documented review of ongoing catheter necessity is a core component of catheter-associated UTI prevention bundles used across healthcare settings.', 2),
('f1000000-0000-0000-0000-000000000038', 'Prophylactic antibiotics are specifically not recommended for catheter-associated UTI prevention, in contrast to the emphasis on aseptic insertion technique and prompt removal.', 3),
('f1000000-0000-0000-0000-000000000039', 'VRE is transmitted primarily via direct contact and contaminated surfaces/equipment, making contact precautions (not airborne or droplet precautions) the appropriate infection control category.', 1),
('f1000000-0000-0000-0000-000000000039', 'Asymptomatic colonisation with a multidrug-resistant organism still warrants infection control measures to prevent onward transmission, distinct from the separate question of whether treatment for active infection is needed.', 2),
('f1000000-0000-0000-0000-000000000039', 'Because VRE is resistant to vancomycin, this option can be identified as pharmacologically illogical as a treatment even before considering that treatment is not indicated for colonisation at all.', 3),
('f1000000-0000-0000-0000-000000000040', $x$Antimicrobial stewardship balances two goals: optimal treatment of the individual patient's infection and protection of antibiotic effectiveness for the wider population by limiting unnecessary resistance selection pressure.$x$, 1),
('f1000000-0000-0000-0000-000000000040', 'Key stewardship interventions include appropriate initial antibiotic choice, timely review and de-escalation once culture results are available, and using the shortest effective duration.', 2),
('f1000000-0000-0000-0000-000000000040', 'Stewardship is distinct from simply restricting antibiotic use; the aim is appropriate, evidence-based prescribing rather than blanket reduction.', 3),
('f1000000-0000-0000-0000-000000000041', 'A history of anaphylaxis (a severe, type I hypersensitivity reaction) represents an absolute contraindication to re-exposure to the causative drug, distinct from milder, non-immediate reactions.', 1),
('f1000000-0000-0000-0000-000000000041', 'Beta-lactam cross-reactivity (between penicillins, cephalosporins and carbapenems) should be considered when selecting an alternative, particularly in patients with severe reaction histories.', 2),
('f1000000-0000-0000-0000-000000000041', 'Checking documented allergy status carefully before prescribing is a fundamental patient safety step, especially for high-risk drug classes like beta-lactams.', 3),
('f1000000-0000-0000-0000-000000000042', 'Aminoglycosides (gentamicin, amikacin) are renally cleared and have a narrow therapeutic index, making dose adjustment in renal impairment essential to avoid toxicity.', 1),
('f1000000-0000-0000-0000-000000000042', 'Therapeutic drug monitoring (measuring peak and/or trough levels) allows individualised dosing to maintain efficacy while minimising nephrotoxicity and ototoxicity risk.', 2),
('f1000000-0000-0000-0000-000000000042', 'Nephrotoxicity from aminoglycosides can further worsen renal function, creating a cycle of drug accumulation if not carefully monitored and adjusted.', 3),
('f1000000-0000-0000-0000-000000000043', 'Trimethoprim inhibits hepatic metabolism of warfarin (via CYP2C9 inhibition), significantly raising INR and bleeding risk when co-prescribed.', 1),
('f1000000-0000-0000-0000-000000000043', 'Any new antibiotic in a patient on warfarin should prompt consideration of both direct drug interactions and altered gut flora affecting vitamin K synthesis, with increased INR monitoring during and after the antibiotic course.', 2),
('f1000000-0000-0000-0000-000000000043', 'Awareness of high-risk interacting antibiotics (trimethoprim, metronidazole, macrolides, fluoroquinolones) is important for safe prescribing in patients on warfarin.', 3),
('f1000000-0000-0000-0000-000000000044', 'Fluoroquinolones carry a specific, well-documented black-box warning for tendinopathy and tendon rupture, most classically affecting the Achilles tendon.', 1),
('f1000000-0000-0000-0000-000000000044', 'Risk factors for this adverse effect include older age, concurrent corticosteroid use, and pre-existing renal impairment or transplant history.', 2),
('f1000000-0000-0000-0000-000000000044', 'Prompt recognition and drug discontinuation are important to prevent progression to complete tendon rupture, which can require surgical repair.', 3),
('f1000000-0000-0000-0000-000000000045', $x$Trimethoprim's mechanism as a folate antagonist underlies its specific association with neural tube defects when used in the first trimester, a critical period for neural tube closure.$x$, 1),
('f1000000-0000-0000-0000-000000000045', $x$Awareness of trimester-specific risks (rather than a blanket 'avoid in pregnancy' rule) is important, as some drugs are more concerning at particular stages (e.g. nitrofurantoin near term) than others.$x$, 2),
('f1000000-0000-0000-0000-000000000045', 'Choosing a safer alternative (e.g. amoxicillin or cefalexin, guided by sensitivities) avoids unnecessary fetal risk while still adequately treating the infection.', 3),
('f1000000-0000-0000-0000-000000000046', 'CURB-65 score guides both severity assessment and site-of-care decisions, with low scores (0-1) generally suitable for oral antibiotics and outpatient or brief inpatient management.', 1),
('f1000000-0000-0000-0000-000000000046', 'Amoxicillin provides appropriate first-line cover against Streptococcus pneumoniae, the most common cause of community-acquired pneumonia, without unnecessary broad-spectrum activity.', 2),
('f1000000-0000-0000-0000-000000000046', 'Reserving broader-spectrum or IV antibiotics for more severe disease (higher CURB-65 scores) reflects appropriate antimicrobial stewardship, avoiding overtreatment of milder infections.', 3),
('f1000000-0000-0000-0000-000000000047', $x$Metronidazole's inhibition of aldehyde dehydrogenase is the specific pharmacological mechanism underlying its well-known disulfiram-like reaction with alcohol.$x$, 1),
('f1000000-0000-0000-0000-000000000047', 'This interaction is a classic, frequently tested point in antimicrobial pharmacology, distinguishing metronidazole from other antibiotics with different interaction profiles (e.g. tetracyclines and dairy/calcium, fluoroquinolones and photosensitivity).', 2),
('f1000000-0000-0000-0000-000000000047', $x$Advising patients to avoid alcohol for a defined period after finishing the course (not just during treatment) reflects the drug's ongoing presence in the body after the last dose.$x$, 3),
('f1000000-0000-0000-0000-000000000048', 'Rifampicin is one of the most potent and clinically important enzyme inducers in prescribing practice, affecting numerous drugs metabolised via the cytochrome P450 system.', 1),
('f1000000-0000-0000-0000-000000000048', 'Reduced phenytoin levels from enzyme induction can lead to breakthrough seizures if the interaction is not anticipated and managed (e.g. with dose adjustment and level monitoring).', 2),
('f1000000-0000-0000-0000-000000000048', $x$Awareness of rifampicin's broad interaction profile (also affecting oral contraceptives, warfarin and other drugs) is important whenever starting TB treatment in a patient on other long-term medications.$x$, 3),
('f1000000-0000-0000-0000-000000000049', 'Red man syndrome is caused by direct, non-immune-mediated histamine release triggered by rapid vancomycin infusion, distinguishing it from true IgE-mediated anaphylaxis.', 1),
('f1000000-0000-0000-0000-000000000049', 'Slowing the infusion rate (and pre-treating with antihistamines if needed) typically allows the reaction to resolve and permits continued vancomycin use, unlike a true allergy requiring permanent avoidance.', 2),
('f1000000-0000-0000-0000-000000000049', 'The classic distribution (face, neck, upper torso flushing) and clear temporal relationship to infusion rate are key clues distinguishing this from other vancomycin adverse effects such as nephrotoxicity or ototoxicity, which develop over a different timescale.', 3),
('f1000000-0000-0000-0000-000000000050', 'Antibiotic sensitivity testing directly informs whether an empirical choice remains appropriate or needs to be changed to an agent the organism is actually susceptible to.', 1),
('f1000000-0000-0000-0000-000000000050', 'Preferring the narrowest effective agent (rather than defaulting to broader-spectrum options) when multiple effective choices are available reflects good antimicrobial stewardship.', 2),
('f1000000-0000-0000-0000-000000000050', $x$Resistance to one antibiotic (here, amoxicillin) does not imply resistance to all others; each agent's individual sensitivity result should guide the specific choice made.$x$, 3);
